globalThis.ANDE_CHUNKS["a230daa85277b81646f88824ffa39b318c53c4d10ad9a41d34b571303df42ea5"] = [{"id":"meituan:3993111040","sourceKey":"meituan","company":"美团","title":"内容安全算法实习生","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3993111040&jobShareType=1","duty":"1.研究大模型前沿技术，包括但不限于预训练，指令微调和强化学习等对齐技术，多模态、可控文本生成等；\n2.负责大模型高效分布式训练和性能优化；\n3.研究模型压缩和推理优化技术，包括但不限于剪枝、量化及知识蒸馏等；\n4.推动大模型在搜索、客服、推荐、广告等场景规模化落地；\n5.参与大模型平台建设。","requirements":"1.硕士及以上学历，计算机、数学、统计学或相关专业；\n2.扎实的算法功底，熟悉自然语言处理和机器学习技术，对技术开发及应用有热情；\n3.熟悉Python/Java等编程语言，有一定工程能力；\n4.熟悉PyTorch/Tensorflow/Megtron等深度学习分布式框架并有实际项目经验；\n5.熟悉Transformer/BERT/GPT等基础模型；\n6.在NLP相关领域顶级会议和期刊发表过论文、在权威评测中取得优秀名次者优先。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.研究大模型前沿技术，包括但不限于预训练，指令微调和强化学习等对齐技术，多模态、可控文本生成等；\n2.负责大模型高效分布式训练和性能优化；\n3.研究模型压缩和推理优化技术，包括但不限于剪枝、量化及知识蒸馏等；\n4.推动大模型在搜索、客服、推荐、广告等场景规模化落地；\n5.参与大模型平台建设。\n\n岗位基本要求\n1.硕士及以上学历，计算机、数学、统计学或相关专业；\n2.扎实的算法功底，熟悉自然语言处理和机器学习技术，对技术开发及应用有热情；\n3.熟悉Python/Java等编程语言，有一定工程能力；\n4.熟悉PyTorch/Tensorflow/Megtron等深度学习分布式框架并有实际项目经验；\n5.熟悉Transformer/BERT/GPT等基础模型；\n6.在NLP相关领域顶级会议和期刊发表过论文、在权威评测中取得优秀名次者优先。\n\n岗位亮点\n1.我们有核心的业务场景，你可以全身心地投入大安全+人工智能的时代浪潮中，建设业界卓越的安全产品、算法； \n2.我们有挑战性的技术愿景，如：超大规模向量检索、大规模预训练、垂类知识图谱等； \n3.我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级，我们尊重知识和常识。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3969981032","sourceKey":"meituan","company":"美团","title":"广告产品实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3969981032&jobShareType=1","duty":"1.协助对接并维护与行业主流广告联盟、DSP平台的合作关系，跟进广告投放的日常运营工作；\n2.对接内部产品、技术、数据等团队，落实广告投放需求，协助完成广告上线、监控与优化；\n3.负责广告相关数据的日常统计与监控，依据业务需求进行数据提取与基础分析，输出数据报表和分析结论；\n4.对接广告投放过程中的数据异常，协助进行问题排查与归因分析，推动问题解决与流程优化；\n5.参与用户投诉的接收、记录及响应处理，协同相关团队给出解决方案，提升用户体验；\n6.协助沉淀广告投放及运营过程中的经验与文档，不断优化工作流程和投放策略。","requirements":"1.研究生及以上在读，专业不限，数学、统计学、计算机、广告、市场营销等相关专业优先；\n2.具备基础 SQL 能力，能独立完成常规数据查询和简单数据分析，有数据敏感度；\n3.逻辑清晰，具备良好的问题拆解与归因能力，愿意深入理解广告投放与平台机制；\n4.具备良好的沟通协作能力和服务意识，能在多团队、多角色协作中高效推进工作；\n5.细致认真，能适应一定节奏的线上投放和客诉处理工作；","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.协助对接并维护与行业主流广告联盟、DSP平台的合作关系，跟进广告投放的日常运营工作；\n2.对接内部产品、技术、数据等团队，落实广告投放需求，协助完成广告上线、监控与优化；\n3.负责广告相关数据的日常统计与监控，依据业务需求进行数据提取与基础分析，输出数据报表和分析结论；\n4.对接广告投放过程中的数据异常，协助进行问题排查与归因分析，推动问题解决与流程优化；\n5.参与用户投诉的接收、记录及响应处理，协同相关团队给出解决方案，提升用户体验；\n6.协助沉淀广告投放及运营过程中的经验与文档，不断优化工作流程和投放策略。\n\n岗位基本要求\n1.研究生及以上在读，专业不限，数学、统计学、计算机、广告、市场营销等相关专业优先；\n2.具备基础 SQL 能力，能独立完成常规数据查询和简单数据分析，有数据敏感度；\n3.逻辑清晰，具备良好的问题拆解与归因能力，愿意深入理解广告投放与平台机制；\n4.具备良好的沟通协作能力和服务意识，能在多团队、多角色协作中高效推进工作；\n5.细致认真，能适应一定节奏的线上投放和客诉处理工作；\n\n具备以下条件优先\n数据敏感，SQL熟练。\n\n岗位亮点\n大平台，数亿流量，前景广阔。如果你对互联网广告、流量投放和数据分析感兴趣，希望从零到一参与实际业务运营，这里能够为你提供深入了解广告平台机制和投放实战的机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3913280155","sourceKey":"meituan","company":"美团","title":"AI功能产品实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3913280155&jobShareType=1","duty":"我们是一款面向内容创作者的AI创作工具产品，团队聚焦智能写作与多模态内容生成，致力于打造新一代的AI内容创作平台。\n我们需要一位具备创新思维和AI产品设计能力的功能产品实习生加入团队，与优秀工程师、设计师协同突破边界，在开放氛围中与产品共同成长，加入之后你将主要负责以下内容：\n\n1. AI能力建设与探索：了解AI能力边界与AI技术在内容创作领域的落地应用，参与产品AI功能设计，为用户提供更智能、更高质量的创作辅助。\n\n2. 创作工具产品功能设计：负责编辑器基础功能需求分析、原型设计及迭代，持续打磨交互细节，提升用户体验。\n\n3. 产品洞察与分析：通过数据监测、用户反馈及行业动态，挖掘核心需求并提出优化建议，为产品决策提供支持","requirements":"经验要求：本科或以上学历，有互联网用户产品/工具产品/AI产品实习经验优先\n\n兴趣驱动：对AIGC和产品创新感兴趣，有内容创作或消费习惯（如小说、剧本、短剧内容）\n\n执行力强：能够推进项目，具备较强的学习能力与创新思维。\n\n用户洞察：具备一定的用户思维，能够理解并挖掘用户在内容创作中的痛点。\n\n数据思维：有数据分析能力和数据sense，能够通过数据来驱动产品优化和策略迭代。\n\n协作沟通：能够跨部门与不同角色高效协作，推动项目落地并执行。\n\n到岗时间：每周保证5天到岗，连续实习3个月以上","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n我们是一款面向内容创作者的AI创作工具产品，团队聚焦智能写作与多模态内容生成，致力于打造新一代的AI内容创作平台。\n我们需要一位具备创新思维和AI产品设计能力的功能产品实习生加入团队，与优秀工程师、设计师协同突破边界，在开放氛围中与产品共同成长，加入之后你将主要负责以下内容：\n\n1. AI能力建设与探索：了解AI能力边界与AI技术在内容创作领域的落地应用，参与产品AI功能设计，为用户提供更智能、更高质量的创作辅助。\n\n2. 创作工具产品功能设计：负责编辑器基础功能需求分析、原型设计及迭代，持续打磨交互细节，提升用户体验。\n\n3. 产品洞察与分析：通过数据监测、用户反馈及行业动态，挖掘核心需求并提出优化建议，为产品决策提供支持\n\n岗位基本要求\n经验要求：本科或以上学历，有互联网用户产品/工具产品/AI产品实习经验优先\n\n兴趣驱动：对AIGC和产品创新感兴趣，有内容创作或消费习惯（如小说、剧本、短剧内容）\n\n执行力强：能够推进项目，具备较强的学习能力与创新思维。\n\n用户洞察：具备一定的用户思维，能够理解并挖掘用户在内容创作中的痛点。\n\n数据思维：有数据分析能力和数据sense，能够通过数据来驱动产品优化和策略迭代。\n\n协作沟通：能够跨部门与不同角色高效协作，推动项目落地并执行。\n\n到岗时间：每周保证5天到岗，连续实习3个月以上\n\n具备以下条件优先\n有内容创作相关经验，如写作、短剧、小说创作等，能理解创作者的痛点和需求。\n\n有AI创作工具产品的使用或设计经验\n\n有从0到1的产品设计经验\n\n具备提示词工程能力和简单的AI coding技能\n\n岗位亮点\n主导项目推进，做有价值的需求\n\n深度接触行业前沿AIGC技术，无边界探索\n\n扁平管理、就事论事、高效决策，拒绝内耗、PUA与办公室政治\n\n团队有活力，带教专业有耐心","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3974173069","sourceKey":"meituan","company":"美团","title":"商业分析实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3974173069&jobShareType=1","duty":"岗位主要负责美团电单车资产端相关分析工作：\n1. 协助/参与到资产核心项目中，跟随Mentor一起，承接包括但不限于策略设计、资产流程优化、规则制定、项目的复盘等工作内容，会涉及到相关业务的数据分析和跟踪\n2. 其他在规划和运营工作中所涉及的工作，或Mentor交办的相关工作","requirements":"1. 思维活跃，能够积极的去思考，具有良好的沟通能力\n2. 具备一定的数据和思维逻辑能力\n3. 强烈的求知欲，能积极面对压力和挑战\n4. 一周至少实习4天，能实习5天，且可长期实习者优先","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n岗位主要负责美团电单车资产端相关分析工作：\n1. 协助/参与到资产核心项目中，跟随Mentor一起，承接包括但不限于策略设计、资产流程优化、规则制定、项目的复盘等工作内容，会涉及到相关业务的数据分析和跟踪\n2. 其他在规划和运营工作中所涉及的工作，或Mentor交办的相关工作\n\n岗位基本要求\n1. 思维活跃，能够积极的去思考，具有良好的沟通能力\n2. 具备一定的数据和思维逻辑能力\n3. 强烈的求知欲，能积极面对压力和挑战\n4. 一周至少实习4天，能实习5天，且可长期实习者优先\n\n岗位亮点\n接触共享出行行业核心资产模块，行业资深专家作为Mentor，进步空间巨大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3620337309","sourceKey":"meituan","company":"美团","title":"公共事务","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3620337309&jobShareType=1","duty":"1.负责公司公共事务管理工作，包括与政府、媒体、社会各界等相关部门进行沟通和协调。\n2.策划和组织公司的政企合作活动，提升公司形象和声誉。\n3.负责危机处理，及时有效地应对各类突发事件。","requirements":"1.大学本科及以上学历，专业不限。\n2.具有丰富的公司公共事务管理经验，有成功案例者优先。\n3.具备优秀的沟通能力、协调能力和团队管理能力。\n4.具有较强的危机处理能力和应变能力。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.负责公司公共事务管理工作，包括与政府、媒体、社会各界等相关部门进行沟通和协调。\n2.策划和组织公司的政企合作活动，提升公司形象和声誉。\n3.负责危机处理，及时有效地应对各类突发事件。\n\n岗位基本要求\n1.大学本科及以上学历，专业不限。\n2.具有丰富的公司公共事务管理经验，有成功案例者优先。\n3.具备优秀的沟通能力、协调能力和团队管理能力。\n4.具有较强的危机处理能力和应变能力。\n\n岗位亮点\n1.可以在公司公共事务管理方面展示个人才华。\n2.参与公司重要活动，与各界名流互动。\n3.带领团队完成各项公共事务任务，实现个人和团队的发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3729719250","sourceKey":"meituan","company":"美团","title":"口腔行业运营实习生","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3729719250&jobShareType=1","duty":"岗位职责\n1.通过对口腔行业和市场的理解，运用科学合理的方式协助行业运营制定相应策略，提升商家活跃度、经营效率、服务水平与经营收益\n2.通过基础数据分析和建设、规则流程或政策制定与培训，通过组织内外部资源协调深度协作，推动策略的运营落地\n3.从用户视角出发，与产品、业务团队深度协作，进行日常指标监控，并制定相关解决方案提升交易转化效率\n4.结合对行业商家经营、行业供给结构、平台产品逻辑及效果调研与理解，梳理用户在交易各路径上的痛点需求，持续推进供给侧主路径优化落地，提升产品效果与客户合作体验","requirements":"工作地点​：上海市\n实习周期​：最少4个月\n\n1.住在上海，稳定一周5天全职实习\n2.对事情有系统的思考，逻辑表达清晰，会使用SQL 等取数工具\n3.强烈的目标导向和分解、落地的能力，积极主动\n4.良好的团队合作意识、能有效组织和协调跨职能、跨部门资源，解决问题，达成目标\n5.有较强的责任心，学习能力、推动力、沟通能力强，有推进项目端到端落地拿结果的能力","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n岗位职责\n1.通过对口腔行业和市场的理解，运用科学合理的方式协助行业运营制定相应策略，提升商家活跃度、经营效率、服务水平与经营收益\n2.通过基础数据分析和建设、规则流程或政策制定与培训，通过组织内外部资源协调深度协作，推动策略的运营落地\n3.从用户视角出发，与产品、业务团队深度协作，进行日常指标监控，并制定相关解决方案提升交易转化效率\n4.结合对行业商家经营、行业供给结构、平台产品逻辑及效果调研与理解，梳理用户在交易各路径上的痛点需求，持续推进供给侧主路径优化落地，提升产品效果与客户合作体验\n\n岗位基本要求\n工作地点​：上海市\n实习周期​：最少4个月\n\n1.住在上海，稳定一周5天全职实习\n2.对事情有系统的思考，逻辑表达清晰，会使用SQL 等取数工具\n3.强烈的目标导向和分解、落地的能力，积极主动\n4.良好的团队合作意识、能有效组织和协调跨职能、跨部门资源，解决问题，达成目标\n5.有较强的责任心，学习能力、推动力、沟通能力强，有推进项目端到端落地拿结果的能力\n\n具备以下条件优先\n▶ 有医疗口腔行业背景知识，患者服务等实践经验，互联网医疗经验优先\n▶ 熟练使用取数和数据可视化工具\n▶ 具有产品经理经历\n\n岗位亮点\n千亿级消费医疗市场，仍保持高速增长\n掌握行业分析、商品运营或品类运营的方法论","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3781589259","sourceKey":"meituan","company":"美团","title":"大数据开发实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3781589259&jobShareType=1","duty":"1.根据外卖业务场景，与各业务团队深入合作，搭建满足外卖一线管理团队，商分，运营，策略等团队日常运营及分析的运营数据体系；\n2.负责规划和设计数据工具和应用系统或产品；协同业务方，PM，RD，QA等资源，完成外卖数据产品推动落地和持续迭代；\n3.通过抽象建设覆盖经营、交易、补贴、营销、流量等主题的数据分析方法和分析思路，赋能业务发展。\n4.负责外卖数仓建设，协同业务后线、运营，提升经营和运营效率。\n5.负责数据平台系统、数据运维系统能力建设，维护系统稳定性。\n6.负责画像平台系统、AI敏捷开发平台能力建设","requirements":"1.掌握hadoop、hive、hbase、ES、Storm、spark、flink一种或者几种平台或组件的开发经验；\n2.掌握数据仓库、ETL开发相关技术和原理，有实时计算经验优先；\n3.掌握JAVA、Python或Scala语言之一，对数据结构和算法设计有较为深刻的理解；\n4.熟悉Linux操作系统，对shell编程有一定了解；\n5.较强的学习、分析和解决问题能力，良好的团队意识和协作精神，有较强的内外沟通能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.根据外卖业务场景，与各业务团队深入合作，搭建满足外卖一线管理团队，商分，运营，策略等团队日常运营及分析的运营数据体系；\n2.负责规划和设计数据工具和应用系统或产品；协同业务方，PM，RD，QA等资源，完成外卖数据产品推动落地和持续迭代；\n3.通过抽象建设覆盖经营、交易、补贴、营销、流量等主题的数据分析方法和分析思路，赋能业务发展。\n4.负责外卖数仓建设，协同业务后线、运营，提升经营和运营效率。\n5.负责数据平台系统、数据运维系统能力建设，维护系统稳定性。\n6.负责画像平台系统、AI敏捷开发平台能力建设\n\n岗位基本要求\n1.掌握hadoop、hive、hbase、ES、Storm、spark、flink一种或者几种平台或组件的开发经验；\n2.掌握数据仓库、ETL开发相关技术和原理，有实时计算经验优先；\n3.掌握JAVA、Python或Scala语言之一，对数据结构和算法设计有较为深刻的理解；\n4.熟悉Linux操作系统，对shell编程有一定了解；\n5.较强的学习、分析和解决问题能力，良好的团队意识和协作精神，有较强的内外沟通能力。\n\n具备以下条件优先\n有数据仓库、大数据开发、BI分析产品建设、实时数据分析、后端开发等1项以上项目经验优先\n\n岗位亮点\n1.能够深入外卖业务，参与快速发展的到家外卖业务，有机会参与面向C端百万级高并发高性能服务；\n2.组内负责外卖数仓核心基建，能够全面参与实时离线一体化的数据仓库建设，负责运营产品和系统的0-1抽象，并形成分析方法论和见证落地过程；\n3.能够接触离线数据开发、实时数据开发、数据分析，高性能C端数据服务，数据系统等全链路建设过程，参与近线、在线数据链路及服务稳定性建设；\n4.跨部门配合较多，并有较多机会参与到关键项目的管理和推进工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3691606760","sourceKey":"meituan","company":"美团","title":"餐饮系统-CRM系统产品运营实习生","city":"成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3691606760&jobShareType=1","duty":"（1）对接来自业务的系统相关问题的解决，并可优化流程通过制定SOP来提升问题解决效率。\n（2）通过制作及完善产品手册，结合日常功能需求上线培训动作，赋能一线提升工具使用效率。\n（3）能洞察业务需求及痛点，并通过线上数据分析，定位产品优化方向。","requirements":"（1）本科及以上在校生，有产品或产运实习经验者优先。\n（2）逻辑清晰，有业务sense；\n（3）责任心强，有耐心。\n（4）良好的沟通协同能力。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n（1）对接来自业务的系统相关问题的解决，并可优化流程通过制定SOP来提升问题解决效率。\n（2）通过制作及完善产品手册，结合日常功能需求上线培训动作，赋能一线提升工具使用效率。\n（3）能洞察业务需求及痛点，并通过线上数据分析，定位产品优化方向。\n\n岗位基本要求\n（1）本科及以上在校生，有产品或产运实习经验者优先。\n（2）逻辑清晰，有业务sense；\n（3）责任心强，有耐心。\n（4）良好的沟通协同能力。\n\n具备以下条件优先\n有过CRM、收单等业务系统实习经历\n\n岗位亮点\n1、有机会接触并参与CRM全业务流程的策略设计；\n2、可承接业务需求，不分产品和产运。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3054133943","sourceKey":"meituan","company":"美团","title":"大模型评测研究与模型研究实习生","city":"上海市/北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3054133943&jobShareType=1","duty":"1.参与面向AGI的大模型评测研究，包括模型性能评估、数据处理等工作；\n2.参与面向AGI的模型训练范式研究，包括算法策略设计、模型调优等工作；\n3.协助团队完成相关项目，按时保质保量完成工作任务。","requirements":"1.大学本科及以上学历，计算机、数学、统计学等相关专业优先；\n2.对机器学习、深度学习等领域有一定了解，有相关实习经验者优先考虑；\n3.具备良好的团队合作能力、沟通能力和学习能力；\n4.熟练掌握Python、C++等编程语言者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.参与面向AGI的大模型评测研究，包括模型性能评估、数据处理等工作；\n2.参与面向AGI的模型训练范式研究，包括算法策略设计、模型调优等工作；\n3.协助团队完成相关项目，按时保质保量完成工作任务。\n\n岗位基本要求\n1.大学本科及以上学历，计算机、数学、统计学等相关专业优先；\n2.对机器学习、深度学习等领域有一定了解，有相关实习经验者优先考虑；\n3.具备良好的团队合作能力、沟通能力和学习能力；\n4.熟练掌握Python、C++等编程语言者优先。\n\n具备以下条件优先\n1. 有Kaggle等平台机器学习比赛获奖经验者优先。\n2. 在计算机领域顶会(如ACL、EMNLP、NeurIPS、ICLR等）上以一作发表过论文者优先；\n3. 具备从事相关行业人工智能开发、算法研究等相关工作经验者优先； \n4. 对大模型有深入了解或丰富的使用经验者优先；\n\n岗位亮点\n1.参与大型模型评测研究项目，接触前沿技术和算法；\n2.获得专业团队的指导和培训，提升自身技能和能力；\n3.有机会转正并长期发展，享受企业完善的福利待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3525122286","sourceKey":"meituan","company":"美团","title":"内容理解项目实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3525122286&jobShareType=1","duty":"1、负责美团视频理解策略的顶层设计，通过标准迭代、策略机制改进等方式，完成需求沟通、标签定义、打标流程建设、数据分析等机制建设，形成解决方案，服务于内容供给和分发等业务场景，推进模型在分发策略中的应用，辅助大盘分发效率提升；\n2、根据对内容的理解、业务诉求，定义视频相关的内容标签体系；\n3、制定算法模型标注SOP、优化人员培训，辅助迭代模型效果；\n4、通过定性、定量方法评估标准合理性，拆解标签质量优化路径，保证标签数据质量和稳定性。","requirements":"1、26届本科及以上在读，一周出勤至少4天，能够实习3个月以上；\n2、有成熟的复杂问题拆解能力，有清晰的逻辑思维以及良好的学习能力，能够快速熟悉和理解复杂的业务流程；\n3、熟悉主流短视频内容平台，对内容趋势、内容热点、优质垂类内容有高度敏感性；\n4、有较强的数据分析和洞察能力，较强的沟通协作能力，能运用数据图表等进行可视化分析，掌握sql加分。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责美团视频理解策略的顶层设计，通过标准迭代、策略机制改进等方式，完成需求沟通、标签定义、打标流程建设、数据分析等机制建设，形成解决方案，服务于内容供给和分发等业务场景，推进模型在分发策略中的应用，辅助大盘分发效率提升；\n2、根据对内容的理解、业务诉求，定义视频相关的内容标签体系；\n3、制定算法模型标注SOP、优化人员培训，辅助迭代模型效果；\n4、通过定性、定量方法评估标准合理性，拆解标签质量优化路径，保证标签数据质量和稳定性。\n\n岗位基本要求\n1、26届本科及以上在读，一周出勤至少4天，能够实习3个月以上；\n2、有成熟的复杂问题拆解能力，有清晰的逻辑思维以及良好的学习能力，能够快速熟悉和理解复杂的业务流程；\n3、熟悉主流短视频内容平台，对内容趋势、内容热点、优质垂类内容有高度敏感性；\n4、有较强的数据分析和洞察能力，较强的沟通协作能力，能运用数据图表等进行可视化分析，掌握sql加分。\n\n岗位亮点\n业务快速增长，成长空间大，团队氛围好，岗位稳定性强","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3168261518","sourceKey":"meituan","company":"美团","title":"项目实习-到餐-软件开发（数据开发及工程开发）","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3168261518&jobShareType=1","duty":"1、参与大规模数据清洗、处理及分析流程的设计与开发，编写高效数据清洗脚本，确保数据质量和处理效率；\n2、完成数据清洗规则实现、异常数据修复及结构化数据转换；\n3、优化数据处理性能，解决高并发、海量数据场景下的技术挑战；\n4、协同产品、算法等团队，推动清洗方案落地并输出标准化文档；\n5、参与数据质量监控工具开发，实现自动化清洗流程。","requirements":"1、掌握hadoop、hive、spark、flink一种或者几种平台或组件的开发经验；\n2、掌握数据仓库、ETL开发相关技术和原理，有实时计算经验优先；\n3、掌握JAVA、Python或Scala语言之一，对数据结构和算法设计有较为深刻的理解；\n4、较强的学习、分析和解决问题能力，良好的团队意识和协作精神，有较强的内外沟通能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、参与大规模数据清洗、处理及分析流程的设计与开发，编写高效数据清洗脚本，确保数据质量和处理效率；\n2、完成数据清洗规则实现、异常数据修复及结构化数据转换；\n3、优化数据处理性能，解决高并发、海量数据场景下的技术挑战；\n4、协同产品、算法等团队，推动清洗方案落地并输出标准化文档；\n5、参与数据质量监控工具开发，实现自动化清洗流程。\n\n岗位基本要求\n1、掌握hadoop、hive、spark、flink一种或者几种平台或组件的开发经验；\n2、掌握数据仓库、ETL开发相关技术和原理，有实时计算经验优先；\n3、掌握JAVA、Python或Scala语言之一，对数据结构和算法设计有较为深刻的理解；\n4、较强的学习、分析和解决问题能力，良好的团队意识和协作精神，有较强的内外沟通能力。\n\n岗位亮点\n1、从理论到实践：将学校中的数据处理经验应用于真实业务场景，积累工业级项目经验；\n2、技术快速成长：接触 大规模数据处理技术栈，掌握 大数据处理 高阶开发技巧；\n3、成果可见：参与美团核心业务建设，跟随业务一起高速成长，直接参与核心数据分析，产出代码及分析的结果将直接与业务场景结合；\n4、团队氛围好：整体年轻化，有大量的共同语言，可以一起成长，尊重各自成员的个性化诉求；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3688620857","sourceKey":"meituan","company":"美团","title":"项目实习-酒店旅行-数据开发-北京","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3688620857&jobShareType=1","duty":"1、负责酒店旅行C端业务数据仓库体系建设，业务数据建模，数据应用产品的研发及管理工作；\n2、负责数据仓库ETL流程设计、开发和优化，解决提升数仓体系生产效率与治理能力；\n3、负责数据仓库OLAP体系搭建，建设海量数据高效、灵活的在线分析应用；\n4、负责实时数仓的建设，使用系统化建设的思维提升实时研发效率，降低生产运维成本\n5、参与挖掘用户相关特征和行为模型,转化数据价值。","requirements":"1.具有扎实的计算机专业知识，极强的问题解决能力；\n2.掌握数据仓库的经典建模方法，熟悉不同建模方法的优劣，2年以上的数仓开发经验；\n3.掌握大数据生态技术栈，具备较丰富的Hadoop、Hive、doris、Spark、flink、kafka等大数据工具应用和开发经验；\n4.扎实的SQL功底，了解不同框架下SQL执行的原理，有过性能优化的实际经验；\n5.优秀的业务理解能力和良好的沟通协调能力；\n6.心态开放，保持好奇心，有自驱力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责酒店旅行C端业务数据仓库体系建设，业务数据建模，数据应用产品的研发及管理工作；\n2、负责数据仓库ETL流程设计、开发和优化，解决提升数仓体系生产效率与治理能力；\n3、负责数据仓库OLAP体系搭建，建设海量数据高效、灵活的在线分析应用；\n4、负责实时数仓的建设，使用系统化建设的思维提升实时研发效率，降低生产运维成本\n5、参与挖掘用户相关特征和行为模型,转化数据价值。\n\n岗位基本要求\n1.具有扎实的计算机专业知识，极强的问题解决能力；\n2.掌握数据仓库的经典建模方法，熟悉不同建模方法的优劣，2年以上的数仓开发经验；\n3.掌握大数据生态技术栈，具备较丰富的Hadoop、Hive、doris、Spark、flink、kafka等大数据工具应用和开发经验；\n4.扎实的SQL功底，了解不同框架下SQL执行的原理，有过性能优化的实际经验；\n5.优秀的业务理解能力和良好的沟通协调能力；\n6.心态开放，保持好奇心，有自驱力。\n\n具备以下条件优先\n1. 参与过从零到一的全流程业务或者某领域的数据仓库设计与实现；\n2. 具备海量数据处理、性能调优者经验；\n3. 熟悉Java/Scala/Python编程语言，有底层源码调优能力优先;\n4. 了解大模型应用，数据湖，挖掘，算法优先。\n\n岗位亮点\n1. 开放的团队氛围，工作内容多样化，参与业务各环节的机会；\n2. 专门的技术支持团队，确保高效沟通和执行；\n3. 鼓励创新，不设限的创意空间，支持想法落地；\n4. 丰富的成长空间和晋升机会，助力个人职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3723476783","sourceKey":"meituan","company":"美团","title":"AI产品运营实习生","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3723476783&jobShareType=1","duty":"1. 撰写并不断迭代大模型prompt提示词，结合业务需求，提升AI的自动化评测能力；\n2. 深度评测大模型效果，结合点评用户需求，给出体验改进报告；\n3. 对点评内/外的新AI功能进行深入体验和调研，输出完整的分析报告；","requirements":"1. 对AI有热情，了解行业内常见的大模型特点，熟练掌握prompt engineer能力。\n2. 心态主动，有想法敢表达，喜欢尝试新事物；\n3. 认真细致，实习时间不低于4个月。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1. 撰写并不断迭代大模型prompt提示词，结合业务需求，提升AI的自动化评测能力；\n2. 深度评测大模型效果，结合点评用户需求，给出体验改进报告；\n3. 对点评内/外的新AI功能进行深入体验和调研，输出完整的分析报告；\n\n岗位基本要求\n1. 对AI有热情，了解行业内常见的大模型特点，熟练掌握prompt engineer能力。\n2. 心态主动，有想法敢表达，喜欢尝试新事物；\n3. 认真细致，实习时间不低于4个月。\n\n岗位亮点\n1. 直接加入点评核心AI项目组，团队小，mentor经验丰富，能给予点对点辅导；\n2. 直接参与模型迭代，了解用户真实反馈，参与到最前沿的AI技术在应用层的落地全流程中。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3692056581","sourceKey":"meituan","company":"美团","title":"无人车业务部-商业分析实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3692056581&jobShareType=1","duty":"1、协助建立和完善业务经营监控指标体系，参与业务日常监控，形成可以对业务诊断和增长驱动的分析体系；\n2、协助进行专题分析，通过深度的数据挖掘和分析，快速发现业务运营中的关键问题。并协助将数据洞察转化为切实可行的解决策略和实施计划，通过持续的改善措施实施，推进业务流程的优化，提升整体运营效率。\n3、协助业务团队制定中长期发展规划，通过设定科学合理的业务目标，构建并持续优化运营评价指标体系。","requirements":"1、2026/2027届研究生及以上学历在读，数学、统计等理工科专业或商科专业优先； \n2、具备扎实的数据分析能力和良好的逻辑思维，精通SQL和办公软件； \n3、学习能力强，具有较强的独立思考能力和快速学习能力，有强烈好奇心； \n4、有互联网或车企数据分析相关实习经验，或对无人车领域一定认知优先； \n5、实习期至少3个月，公司办公至少4天/周，能尽快到岗优先。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、协助建立和完善业务经营监控指标体系，参与业务日常监控，形成可以对业务诊断和增长驱动的分析体系；\n2、协助进行专题分析，通过深度的数据挖掘和分析，快速发现业务运营中的关键问题。并协助将数据洞察转化为切实可行的解决策略和实施计划，通过持续的改善措施实施，推进业务流程的优化，提升整体运营效率。\n3、协助业务团队制定中长期发展规划，通过设定科学合理的业务目标，构建并持续优化运营评价指标体系。\n\n岗位基本要求\n1、2026/2027届研究生及以上学历在读，数学、统计等理工科专业或商科专业优先； \n2、具备扎实的数据分析能力和良好的逻辑思维，精通SQL和办公软件； \n3、学习能力强，具有较强的独立思考能力和快速学习能力，有强烈好奇心； \n4、有互联网或车企数据分析相关实习经验，或对无人车领域一定认知优先； \n5、实习期至少3个月，公司办公至少4天/周，能尽快到岗优先。\n\n岗位亮点\n亲眼见证科技对商业的改变，亲身参与并推动革新中国即时服务行业；\n参与美团“零售+科技”的第二成长曲线的快速发展的业务氛围，探索并推动业务找到加速商业化发展的方向；\n无人车、人工智能等业界前沿科技话题的研究实践经历，与国内外精英并肩作战的难得机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3802835253","sourceKey":"meituan","company":"美团","title":"大模型社区技术内容运营（Technical Writer）","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3802835253&jobShareType=1","duty":"1. 负责大模型评测社区技术内容编辑，主要根据原始素材，对模型评测结果、模型评测榜单、评测技术等内容进行编辑；\n2. 负责社区技术内容的规范化输出，和运营共同合作打造有价值和影响力的技术传播内容；\n3. 与算法工程师、评测运营、产品经理紧密合作，根据需求以及原始素材，进行各类文档的编写，保证内容的一致性以及易读性；\n4. 参与制定和改进技术内容运营的流程、规范，收集和处理用户反馈，持续提升文档质量与用户体验。","requirements":"1. 本科及以上学历，计算机以及相关专业；\n2. 具备优秀的语言理解能力、信息架构能力，以及文档写作能力；\n3. 较强的英语写作能力，能撰写规范的英语技术文档；\n4. 学习能力强，能快速学习掌握大模型及评测领域知识；\n5. 积极主动，善于思考，处事高效，能适应快速迭代的工作环境；\n5. 具备良好的项目管理、沟通及协调能力，有强烈的责任心，勇于接受挑战。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责大模型评测社区技术内容编辑，主要根据原始素材，对模型评测结果、模型评测榜单、评测技术等内容进行编辑；\n2. 负责社区技术内容的规范化输出，和运营共同合作打造有价值和影响力的技术传播内容；\n3. 与算法工程师、评测运营、产品经理紧密合作，根据需求以及原始素材，进行各类文档的编写，保证内容的一致性以及易读性；\n4. 参与制定和改进技术内容运营的流程、规范，收集和处理用户反馈，持续提升文档质量与用户体验。\n\n岗位基本要求\n1. 本科及以上学历，计算机以及相关专业；\n2. 具备优秀的语言理解能力、信息架构能力，以及文档写作能力；\n3. 较强的英语写作能力，能撰写规范的英语技术文档；\n4. 学习能力强，能快速学习掌握大模型及评测领域知识；\n5. 积极主动，善于思考，处事高效，能适应快速迭代的工作环境；\n5. 具备良好的项目管理、沟通及协调能力，有强烈的责任心，勇于接受挑战。\n\n岗位亮点\n1. 和国内前沿大模型团队一起成长，掌握最前沿的大模型知识和理论，积累行业经验；\n2. 深度参与社区的运营，积累社区运营的一线经验；\n3. 与产品、算法、运营团队密切合作，培养跨团队沟通协作能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3779779839","sourceKey":"meituan","company":"美团","title":"大模型数据运营实习生","city":"北京市/上海市/成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3779779839&jobShareType=1","duty":"负责AI模型训练及评测相关的数据运营工作，与算法团队配合不断优化提升AI模型效果。具体工作内容包括：\n1. 明确大模型训练及评测场景中的数据需求，进行需求梳理、方案制定和质检，交付高质量数据；\n2. 建立有效的培训、质检、沟通等机制，保障数据的高质量高效率交付；\n3. 建立有效的数据分类和管理机制，为相关团队提供高效可靠的数据获取方案；\n4. 与各相关部门保持良好沟通，收集并协调各方数据需求，为项目提供数据运营相关支持。","requirements":"1. 2026届及以后，本科及以上学历在读，语言类、数学类、计算机等相关专业优先；\n2. 逻辑清晰，具备较强的学习能力及协调能力，能快速熟练掌握各类判别标准，工作细致，有团队合作意识；\n3. 具备数据分析能力，能熟练使用各类办公及工具软件。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责AI模型训练及评测相关的数据运营工作，与算法团队配合不断优化提升AI模型效果。具体工作内容包括：\n1. 明确大模型训练及评测场景中的数据需求，进行需求梳理、方案制定和质检，交付高质量数据；\n2. 建立有效的培训、质检、沟通等机制，保障数据的高质量高效率交付；\n3. 建立有效的数据分类和管理机制，为相关团队提供高效可靠的数据获取方案；\n4. 与各相关部门保持良好沟通，收集并协调各方数据需求，为项目提供数据运营相关支持。\n\n岗位基本要求\n1. 2026届及以后，本科及以上学历在读，语言类、数学类、计算机等相关专业优先；\n2. 逻辑清晰，具备较强的学习能力及协调能力，能快速熟练掌握各类判别标准，工作细致，有团队合作意识；\n3. 具备数据分析能力，能熟练使用各类办公及工具软件。\n\n具备以下条件优先\n对ChatGPT等大模型有深入了解或丰富的使用经验者优先\n\n岗位亮点\n1. 紧跟人工智能行业的前沿进展，接触到新的技术和行业趋势，磨练出对人工智能的独到见解；\n2. 参与AI模型的训练与评测流程，了解从理论到工程实践的全面技能；\n3. 与一流的人工智能团队合作，快速成长，提升自身能力；\n4. 有机会参与公司的创新项目，跨足不同领域，拓宽人工智能技术的应用范围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3598204228","sourceKey":"meituan","company":"美团","title":"美团招聘实习生-酒旅业务线","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3598204228&jobShareType=1","duty":"1、对接业务需求，通过主动寻访等方式，与优秀候选人建立联系，并甄选合适的人才；\n2、通过多方协同，推进面试流程，保障应聘者和用人经理良好的面试体验；\n3、管理招聘流程相关数据，对于异常数据及时与相关方沟通，推进问题解决。","requirements":"1、本科或研究生，专业不限，大三、研一学生优先；\n2、有人力资源相关工作经验优先；\n3、良好的沟通能力、细致认真、责任心强、思路清晰；\n4、能够连续实习4个月及以上，每周出勤5天优先。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1、对接业务需求，通过主动寻访等方式，与优秀候选人建立联系，并甄选合适的人才；\n2、通过多方协同，推进面试流程，保障应聘者和用人经理良好的面试体验；\n3、管理招聘流程相关数据，对于异常数据及时与相关方沟通，推进问题解决。\n\n岗位基本要求\n1、本科或研究生，专业不限，大三、研一学生优先；\n2、有人力资源相关工作经验优先；\n3、良好的沟通能力、细致认真、责任心强、思路清晰；\n4、能够连续实习4个月及以上，每周出勤5天优先。\n\n岗位亮点\n1、团队氛围好，成长机会多；\n2、通过实习能够深刻的理解公司选人标准，有助于为自己做清晰的职业规划。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3258846670","sourceKey":"meituan","company":"美团","title":"【实习】境外酒店直连产品实习生","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3258846670&jobShareType=1","duty":"1.负责境外酒店直连相关的产品需求分析与方案设计，推进产品功能落地。\n2.协助团队进行市场调研和分析，为产品优化提供参考意见。\n3.跟进产品运营数据，及时发现问题并提出功能工具优化方案，提升业务运营效率。\n4.负责产品的测试和问题排查，及时修复和优化产品的性能和用户体验。","requirements":"1.大学本科及以上学历，计算机相关专业优先考虑。\n2.对互联网行业和产品开发流程有一定的了解和热情。\n3.具备良好的逻辑思维能力和问题解决能力，能够快速理解和分析复杂的业务需求。\n4.具备良好的数据分析能力。\n5.实习不少于三个月，保证出勤4-5天/周。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责境外酒店直连相关的产品需求分析与方案设计，推进产品功能落地。\n2.协助团队进行市场调研和分析，为产品优化提供参考意见。\n3.跟进产品运营数据，及时发现问题并提出功能工具优化方案，提升业务运营效率。\n4.负责产品的测试和问题排查，及时修复和优化产品的性能和用户体验。\n\n岗位基本要求\n1.大学本科及以上学历，计算机相关专业优先考虑。\n2.对互联网行业和产品开发流程有一定的了解和热情。\n3.具备良好的逻辑思维能力和问题解决能力，能够快速理解和分析复杂的业务需求。\n4.具备良好的数据分析能力。\n5.实习不少于三个月，保证出勤4-5天/周。\n\n具备以下条件优先\n1. 数据导向，熟悉SQL等数据分析工具。\n2.了解编程语言基础语法\n2. 有过互联网实习经历优先。\n\n岗位亮点\n1.贴近一线业务，可以深入学习了解酒旅行业知识，锻炼产品专业技能。\n2.团队氛围好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3040997352","sourceKey":"meituan","company":"美团","title":"招聘HR实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3040997352&jobShareType=1","duty":"1.协助招聘经理完成招聘计划，负责招聘流程中的简历筛选、面试安排等工作。\n2.负责编写并发布招聘广告，通过各种渠道积极寻找合适的候选人。\n3.跟进招聘流程，与候选人进行沟通，安排面试并提供必要的面试反馈。\n4.维护和更新招聘数据库，确保招聘信息的准确性和及时性。","requirements":"1.大学本科及以上学历，人力资源管理、心理学或相关专业优先考虑。\n2.具备良好的沟通能力和团队合作意识，能够与各部门有效配合。\n3.熟悉招聘流程和相关法律法规，了解常用的招聘渠道和方法。\n4.具备较强的组织和协调能力，能够有效安排面试和处理各类招聘事务。\n5.具备较强的学习能力和适应能力，能够快速融入团队并承担工作压力。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.协助招聘经理完成招聘计划，负责招聘流程中的简历筛选、面试安排等工作。\n2.负责编写并发布招聘广告，通过各种渠道积极寻找合适的候选人。\n3.跟进招聘流程，与候选人进行沟通，安排面试并提供必要的面试反馈。\n4.维护和更新招聘数据库，确保招聘信息的准确性和及时性。\n\n岗位基本要求\n1.大学本科及以上学历，人力资源管理、心理学或相关专业优先考虑。\n2.具备良好的沟通能力和团队合作意识，能够与各部门有效配合。\n3.熟悉招聘流程和相关法律法规，了解常用的招聘渠道和方法。\n4.具备较强的组织和协调能力，能够有效安排面试和处理各类招聘事务。\n5.具备较强的学习能力和适应能力，能够快速融入团队并承担工作压力。\n\n岗位亮点\n1.能够接触到各类候选人，了解不同行业和岗位的需求。\n2.参与招聘流程中的各个环节，能够全面了解和掌握招聘工作的各个方面。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3772211058","sourceKey":"meituan","company":"美团","title":"餐饮SaaS产品项目实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3772211058&jobShareType=1","duty":"1、产品运营效率‌提升：‌\n通过分析产品销售数据，‌发现用户的使用习惯和需求，‌从而优化产品市场运营策略。同时，支持撰写产品售卖相关的宣传物料，配合给前线业务宣传培训。\n2、数据维护和优化清洗：\n日常维护、清洗品牌的底层数据，日常跟进产品行业数据准确率的校准，同时配合梳理数据校准、优化方案。","requirements":"1.本科及以上在校生，具有数学、统计学和计算机相关知识基础，熟悉数据查询语言。\n2.有良好的数据敏感度、较强的逻辑思维能力和洞察力，对数据问题定位和数据可视化有自己的认识。\n3.具有较强的业务理解，数据抽象与定义能力。\n4.有良好的跨团队的沟通能力。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1、产品运营效率‌提升：‌\n通过分析产品销售数据，‌发现用户的使用习惯和需求，‌从而优化产品市场运营策略。同时，支持撰写产品售卖相关的宣传物料，配合给前线业务宣传培训。\n2、数据维护和优化清洗：\n日常维护、清洗品牌的底层数据，日常跟进产品行业数据准确率的校准，同时配合梳理数据校准、优化方案。\n\n岗位基本要求\n1.本科及以上在校生，具有数学、统计学和计算机相关知识基础，熟悉数据查询语言。\n2.有良好的数据敏感度、较强的逻辑思维能力和洞察力，对数据问题定位和数据可视化有自己的认识。\n3.具有较强的业务理解，数据抽象与定义能力。\n4.有良好的跨团队的沟通能力。\n\n具备以下条件优先\n1.有产品岗实习经验者优先。\n2.有数据处理、数据分析经验者优先。\n3.有商业化产品外宣材料撰写经验者优先。\n\n岗位亮点\n【个人成长】该岗位未来工作，无论在横向部门协同，还是外部客户对接上都有较多的接触机会，对激发个人潜力和能力提升都能够全面的有所锻炼;\n【团队氛围】开放和直接的沟通环境，注重打好基础和苦练基本功，非常有利于个人职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3643704509","sourceKey":"meituan","company":"美团","title":"服务零售数仓项目实习生","city":"上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3643704509&jobShareType=1","duty":"1.数据仓库的建设、组织和管理，沉淀数据资产；\n2.数据建设过程的各项工具研发，如数据安全、数据质量、数据开发的工具链等；\n3.数据应用的研发，如商业智能、挖掘、分析报告、数据可视化等；\n4.其他服务于业务各环节的数据运营工作。","requirements":"1.计算机、信息技术相关专业本科以上学历，对数据技术感兴趣；\n2.熟练掌握至少一种编程语言（包括但不限于Python、Java、C++等），熟练掌握算法数据结构，有编程实践经验；\n3.掌握数据库基本原理和知识，熟练使用SQL。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.数据仓库的建设、组织和管理，沉淀数据资产；\n2.数据建设过程的各项工具研发，如数据安全、数据质量、数据开发的工具链等；\n3.数据应用的研发，如商业智能、挖掘、分析报告、数据可视化等；\n4.其他服务于业务各环节的数据运营工作。\n\n岗位基本要求\n1.计算机、信息技术相关专业本科以上学历，对数据技术感兴趣；\n2.熟练掌握至少一种编程语言（包括但不限于Python、Java、C++等），熟练掌握算法数据结构，有编程实践经验；\n3.掌握数据库基本原理和知识，熟练使用SQL。\n\n岗位亮点\n1.团队氛围好、活动多、同事好Nice；\n2.与产品、算法、分析和工程一起紧密协作，做数据闭环的事；\n3.行业丰富度高，数据赋能业务的空间大；\n4.海量数据处理的机会，接触并能应用到数据领域新技术；\n5.与O2O、广告、推荐、数据、人工智能等多元化背景的团队技术大牛一起学习成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3728728037","sourceKey":"meituan","company":"美团","title":"多模态大模型算法实习生（语音方向）","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3728728037&jobShareType=1","duty":"1. 优化语音合成线上效果，探索语音新范式以及语音大模型等前沿技术；\n2. 研究音乐、歌唱合成以及歌唱转换等方向，给视频化提供更丰富的能力；\n3. 探索全流式语音合成，以及优化音频编辑技术效果；\n4. 持续优化视频配音效果，结合业务需求提供多样化强表现力的配音能力。","requirements":"1. 熟练掌握Python或C++等编程语言；\n2. 熟悉常见机器学习、深度学习算法；\n3. 具备强烈的技术好奇心和学习能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 优化语音合成线上效果，探索语音新范式以及语音大模型等前沿技术；\n2. 研究音乐、歌唱合成以及歌唱转换等方向，给视频化提供更丰富的能力；\n3. 探索全流式语音合成，以及优化音频编辑技术效果；\n4. 持续优化视频配音效果，结合业务需求提供多样化强表现力的配音能力。\n\n岗位基本要求\n1. 熟练掌握Python或C++等编程语言；\n2. 熟悉常见机器学习、深度学习算法；\n3. 具备强烈的技术好奇心和学习能力。\n\n具备以下条件优先\n1. 曾参与语音大模型、音乐、多模态等相关项目的实习经验；\n2. 具备深度学习训练平台或推理引擎研发经验；\n3. 具备语音方向相关经验。\n\n岗位亮点\n1. 你将加入优秀的团队，一起成长：团队高阶研发密度大，汇聚行业大牛，分享交流活动多；\n2. 你将负责前沿技术的探究：热门智能技术发展方向，未来拥有广阔的应用前景；\n3. 你将拥有快速成长的空间，一起见证技术落地的喜悦：部门业务处于快速发展阶段，应用场景广泛，业务落地场景丰富，复杂度高，挑战性大；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3661397768","sourceKey":"meituan","company":"美团","title":"内容中台产品经理（实习）","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3661397768&jobShareType=1","duty":"1、参与内容处理中台能力建设，包括但不限于搭建标准化的通用内容管线中台能力、内容理解及打标体系、审核链路、媒资工具，拉通全链路各处理环节，完成内容链路处理闭环，对内容处理效率和特征质量负责；\n2、协同多业务部门，整合业务及中台内容资源，规范内容处理全流程机制和合作模式，提高部门间协同效率；\n3、基于部门目标，与运营和研发团队协同，制定周期性阶段目标，把控业务方向，拆解任务，确保需求高质量落实。","requirements":"1、需要熟练使用sql（强要求），具备一定的数据分析与数据整理能力；\n2、有内容行业经验、熟悉内容全生命周期的产品链路和流程者加分；\n3、良好的语言沟通与表达能力，善于与多业务协同沟通，促成中台与业务高效协作;\n4、客户意识强，具有用户同理心，能够站在用户对产品使用视角审视、发现并快速解决问题;\n5、有良好的心态，能很好适应多业务变化，灵活调整团队节奏和打法；\n6、提炼总结和汇报能力强。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、参与内容处理中台能力建设，包括但不限于搭建标准化的通用内容管线中台能力、内容理解及打标体系、审核链路、媒资工具，拉通全链路各处理环节，完成内容链路处理闭环，对内容处理效率和特征质量负责；\n2、协同多业务部门，整合业务及中台内容资源，规范内容处理全流程机制和合作模式，提高部门间协同效率；\n3、基于部门目标，与运营和研发团队协同，制定周期性阶段目标，把控业务方向，拆解任务，确保需求高质量落实。\n\n岗位基本要求\n1、需要熟练使用sql（强要求），具备一定的数据分析与数据整理能力；\n2、有内容行业经验、熟悉内容全生命周期的产品链路和流程者加分；\n3、良好的语言沟通与表达能力，善于与多业务协同沟通，促成中台与业务高效协作;\n4、客户意识强，具有用户同理心，能够站在用户对产品使用视角审视、发现并快速解决问题;\n5、有良好的心态，能很好适应多业务变化，灵活调整团队节奏和打法；\n6、提炼总结和汇报能力强。\n\n岗位亮点\n交易与内容双轮驱动，为业务提供高效、低成本且有价值的内容","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3600233708","sourceKey":"meituan","company":"美团","title":"支付商业分析实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3600233708&jobShareType=1","duty":"1、日常数据监控：进行日常数据报表的监测，能够及时发现问题并分析数据异常原因。\n2、异动归因：数据监控并识别异动，进行异动分析，归因业务原因，产出结论。\n3、业务数据分析：协助进行专题分析，深挖数据体现的业务问题，产出有应用性的数据结论。\n4、策略评估：协助进行策略分析工作，产出实验效果和结论。\n5、完成mentor交代的其他工作。","requirements":"1、具备良好的数理逻辑思考能力、业务理解能力和沟通表达能力。\n2、对数据敏感，学习能力强，能够快速掌握公司内部各种数据工具。\n3、熟练使用Hive/SQL，掌握基本的数据可视化和统计方法，并有相关实习经历。\n4、一周4-5天，并能持续3个月及以上。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、日常数据监控：进行日常数据报表的监测，能够及时发现问题并分析数据异常原因。\n2、异动归因：数据监控并识别异动，进行异动分析，归因业务原因，产出结论。\n3、业务数据分析：协助进行专题分析，深挖数据体现的业务问题，产出有应用性的数据结论。\n4、策略评估：协助进行策略分析工作，产出实验效果和结论。\n5、完成mentor交代的其他工作。\n\n岗位基本要求\n1、具备良好的数理逻辑思考能力、业务理解能力和沟通表达能力。\n2、对数据敏感，学习能力强，能够快速掌握公司内部各种数据工具。\n3、熟练使用Hive/SQL，掌握基本的数据可视化和统计方法，并有相关实习经历。\n4、一周4-5天，并能持续3个月及以上。\n\n岗位亮点\n完善的商分培养体系，掌握商分方法论，并在实际工作中对业务产生价值。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3094471749","sourceKey":"meituan","company":"美团","title":"餐饮行业策略运营（实习）","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3094471749&jobShareType=1","duty":"1.参与餐饮行业的相关数据分析、用户研究、策略制定。\n2.参与推进行业策略的落地，并能对策略提出改进建议和方案。\n3.与餐饮相关业务配合密切，不断收集和发现相关用户需求、产品痛点和业务增长机会。\n4.参与用户调研和访谈、监测相关产品/公司的类似策略和行动，及时调整和优化已经制定的行业策略。","requirements":"1.大学本科及以上学历，每周实习4天及以上，最少实习3个月以上，时间更长的优先考虑。\n2.具备数据分析和数据驱动的能力，熟练运用用户分析工具和数据分析工具。\n3.具备良好的沟通协调能力和团队合作精神，能够与不同团队较好合作，推动项目进展。\n4.具备良好的学习能力、好奇心和创新意识，能够不断学习和跟进行业动态。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.参与餐饮行业的相关数据分析、用户研究、策略制定。\n2.参与推进行业策略的落地，并能对策略提出改进建议和方案。\n3.与餐饮相关业务配合密切，不断收集和发现相关用户需求、产品痛点和业务增长机会。\n4.参与用户调研和访谈、监测相关产品/公司的类似策略和行动，及时调整和优化已经制定的行业策略。\n\n岗位基本要求\n1.大学本科及以上学历，每周实习4天及以上，最少实习3个月以上，时间更长的优先考虑。\n2.具备数据分析和数据驱动的能力，熟练运用用户分析工具和数据分析工具。\n3.具备良好的沟通协调能力和团队合作精神，能够与不同团队较好合作，推动项目进展。\n4.具备良好的学习能力、好奇心和创新意识，能够不断学习和跟进行业动态。\n\n具备以下条件优先\n数据分析、sql能力\n\n岗位亮点\n1.接触互联网大厂TOP规模餐饮行业用户策略制定，能够深入了解和把握行业发展趋势。\n2.可以与产品、技术、市场等多个团队紧密合作，拓展自己的专业能力和职业经历。\n3.可以通过数据分析和用户运营策略的优化，直接影响和提升产品的市场竞争力。\n4. 有参与公司S级、A级项目机会，获得宝贵实习经验。\n5. 团队年轻人多、氛围轻松欢乐、互相学习。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3379269866","sourceKey":"meituan","company":"美团","title":"【实习】质量工程基建-项目实习生","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3379269866&jobShareType=1","duty":"1. 参与研发基础设施建设工作。\n2. 参与新技术的探索、应用和落地，参与智能化测试的探索。\n3. 参与对业务开发和测试团队的技术支持。","requirements":"1. 对工程质量和工程效率领域具有长期的热情，具备充分的韧性与主动性。\n2. 本科及以上学历，计算机或其他相关专业，计算机技术基础扎实，至少掌握Java、Python、VUE等编程语言中的一种。\n3. 落地并持续改进多种测试框架和工具，并有针对性地做出迭代改进以及创新，能结合AI技术对已有工具系统进行智能化改造。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 参与研发基础设施建设工作。\n2. 参与新技术的探索、应用和落地，参与智能化测试的探索。\n3. 参与对业务开发和测试团队的技术支持。\n\n岗位基本要求\n1. 对工程质量和工程效率领域具有长期的热情，具备充分的韧性与主动性。\n2. 本科及以上学历，计算机或其他相关专业，计算机技术基础扎实，至少掌握Java、Python、VUE等编程语言中的一种。\n3. 落地并持续改进多种测试框架和工具，并有针对性地做出迭代改进以及创新，能结合AI技术对已有工具系统进行智能化改造。\n\n具备以下条件优先\n1. 对AI Agent、MCP等有开发实践经验\n2. 有开源项目经验\n\n岗位亮点\n1. 业务极具挑战。\n2. 团队气氛融洽，技术氛围浓厚，对新员工有完善的培训和指导体系，与各部门合作紧密，配合默契。\n3. 团队拥有优秀的人才，前瞻的技术，成熟的机制，积极的学习氛围以及探索精神，内部多位技术专家在GIAC、MTSC、QECon等技术峰会上与业界同行进行分享与交流。\n4. 期待在智能化测试的探索道路上与你同行！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3575843390","sourceKey":"meituan","company":"美团","title":"团购频道产品实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3575843390&jobShareType=1","duty":"美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销、前端技术基础设施建设以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。","requirements":"1、参与和协助频道导购路径、流程体验的产品设计和优化，提升频道流量转化效率、用户体验和用户复访复购；\n2、深入分析和洞察用户到店吃喝玩乐住的需求，通过优化频道页和货架、搭建营销场等方式，提升用户需求与供给的匹配效率；\n3、协同平台产研运团队、业务产研运团队，推动产品功能上线，挖掘用户不同场景的需求，与团队一起探索理想的产品设计满足对应差异化需求。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销、前端技术基础设施建设以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位基本要求\n1、参与和协助频道导购路径、流程体验的产品设计和优化，提升频道流量转化效率、用户体验和用户复访复购；\n2、深入分析和洞察用户到店吃喝玩乐住的需求，通过优化频道页和货架、搭建营销场等方式，提升用户需求与供给的匹配效率；\n3、协同平台产研运团队、业务产研运团队，推动产品功能上线，挖掘用户不同场景的需求，与团队一起探索理想的产品设计满足对应差异化需求。\n\n具备以下条件优先\n1、1年以上互联网产品实习经验，有本地生活和电商平台经历者优先，有营销产品和交易产品经历优先；\n2、以用户为中心，对用户场景和需求有深入理解和洞察，对用户体验有足够的敏感度；\n3、较强的主人翁意识，拥有高效的执行力、具备较好的数据和逻辑思维。\n\n岗位亮点\n1、参与团购频道建设，积累服务电商和本地生活领域的产品经验，并有深入了解美团多业务、培养商业思维的机会；\n2、核心业务，靠谱团队，团队氛围简单友好，鼓励思考和关注个人成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3159876283","sourceKey":"meituan","company":"美团","title":"无人机运行系统项目实习生","city":"北京市/深圳市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3159876283&jobShareType=1","duty":"1. 系统设计与开发：参与美团无人机机场运行系统的设计、开发和维护工作；\n2. 产品和系统优化：根据项目需求，进行代码编写、单元测试和系统优化，确保系统稳定性和性能；\n3. 技术预研与规划：调研学界与业界在航空领域、物流领域等相关领域内的研究成果、技术方案、行业标准。","requirements":"1. 本科及以上在校生，计算机相关专业优先；\n2. 对软件开发有浓厚兴趣，有较强的学习能力和团队合作意识；\n3. 熟悉Java、C++等编程语言，熟悉数据库原理和常用开发框架；\n4. 有良好的团队协作意识和沟通协调能力。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 系统设计与开发：参与美团无人机机场运行系统的设计、开发和维护工作；\n2. 产品和系统优化：根据项目需求，进行代码编写、单元测试和系统优化，确保系统稳定性和性能；\n3. 技术预研与规划：调研学界与业界在航空领域、物流领域等相关领域内的研究成果、技术方案、行业标准。\n\n岗位基本要求\n1. 本科及以上在校生，计算机相关专业优先；\n2. 对软件开发有浓厚兴趣，有较强的学习能力和团队合作意识；\n3. 熟悉Java、C++等编程语言，熟悉数据库原理和常用开发框架；\n4. 有良好的团队协作意识和沟通协调能力。\n\n具备以下条件优先\n1. 有大型分布式系统研发经验者优先；\n\n岗位亮点\n1. 参与无人机配送分布式航网的建设，深入了解无人机业务和技术；\n2. 和无人机前沿技术专家共事，获得专业团队的指导和培训。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3532538442","sourceKey":"meituan","company":"美团","title":"AI产品实习生","city":"北京市/广州市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3532538442&jobShareType=1","duty":"1.进行用户需求调研和用户行为分析，收集和整理用户反馈和数据，为产品设计提供支持。\n2.参与AI产品的需求分析、设计和开发工作，协助团队完成产品功能的优化和迭代。\n3.参与产品迭代优化，发现和解决产品中的问题，提高产品质量和用户体验。","requirements":"1.大学本科及以上学历，计算机、人工智能、市场营销等相关专业优先。\n2.对人工智能技术有浓厚兴趣，熟悉常用的AI产品和工具，有较强的学习能力和解决问题能力。\n3.具备良好的团队合作精神和沟通能力，有较强的学习能力和解决问题的能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.进行用户需求调研和用户行为分析，收集和整理用户反馈和数据，为产品设计提供支持。\n2.参与AI产品的需求分析、设计和开发工作，协助团队完成产品功能的优化和迭代。\n3.参与产品迭代优化，发现和解决产品中的问题，提高产品质量和用户体验。\n\n岗位基本要求\n1.大学本科及以上学历，计算机、人工智能、市场营销等相关专业优先。\n2.对人工智能技术有浓厚兴趣，熟悉常用的AI产品和工具，有较强的学习能力和解决问题能力。\n3.具备良好的团队合作精神和沟通能力，有较强的学习能力和解决问题的能力。\n\n具备以下条件优先\n1、有AI产品、用户产品实习经验优先；\n2、对大模型行业了解，有过AI coding经验优先；\n\n岗位亮点\n1.参与大模型的用户产品探索，了解人工智能技术和产品设计前沿趋势，提升自己的产品能力。\n2.与一流的产品经理和开发团队合作，学习和掌握产品设计和开发流程，了解产品上线和运营的全过程。\n3.团队氛围好，可获得丰富的实践经验，参与产品的设计、测试和优化，锻炼问题解决和团队合作能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3394933538","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【Reasoning能力提升】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3394933538&jobShareType=1","duty":"【课题说明】\n通用模型往往难以兼顾多样化的场景需求，容易出现泛化能力强但针对性不足的问题。针对这一挑战，本课题聚焦于研究面向具体业务或应用场景的强化学习训练优化策略，通过引入场景特定的奖励函数、环境建模和数据采样机制，提升模型在特定任务下的表现能力与适应性。课题重点突破模型在细粒度场景下的泛化能力不足、奖励稀疏、训练效率低等问题，为大模型的行业落地提供有力支撑。\n【建议研究方向】\n1.场景特定奖励设计：针对不同业务场景，定制化设计奖励函数，提升模型在目标任务中的表现能力。\n2.环境模拟与数据生成：构建高保真场景模拟环境，开发高效的数据采样与生成机制，提升强化学习训练效率。\n3.迁移与泛化能力增强：研究多场景迁移学习与元强化学习方法，提升模型从通用能力到场景定制能力的转化效率。\n4.推理增强型RAG系统：基于图结构的知识融合、混合模型的协同推理架构和强化学习驱动的优化方法，进一步提升RAG系统能力。\n5.基于价值观约束的大模型风险控制与安全防护。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n通用模型往往难以兼顾多样化的场景需求，容易出现泛化能力强但针对性不足的问题。针对这一挑战，本课题聚焦于研究面向具体业务或应用场景的强化学习训练优化策略，通过引入场景特定的奖励函数、环境建模和数据采样机制，提升模型在特定任务下的表现能力与适应性。课题重点突破模型在细粒度场景下的泛化能力不足、奖励稀疏、训练效率低等问题，为大模型的行业落地提供有力支撑。\n【建议研究方向】\n1.场景特定奖励设计：针对不同业务场景，定制化设计奖励函数，提升模型在目标任务中的表现能力。\n2.环境模拟与数据生成：构建高保真场景模拟环境，开发高效的数据采样与生成机制，提升强化学习训练效率。\n3.迁移与泛化能力增强：研究多场景迁移学习与元强化学习方法，提升模型从通用能力到场景定制能力的转化效率。\n4.推理增强型RAG系统：基于图结构的知识融合、混合模型的协同推理架构和强化学习驱动的优化方法，进一步提升RAG系统能力。\n5.基于价值观约束的大模型风险控制与安全防护。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3396084629","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【多场景Agent】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3396084629&jobShareType=1","duty":"【课题说明】\n以大模型对话技术为核心，探索前沿技术问题。研究方向包括角色扮演、个性化对话、记忆管理，拟人化，数字人等，主要业务场景包括运营，招聘，销售，审核等。目标是构建覆盖多个场景的Agent系统，实现“技术驱动业务范式”的升级转变。\n【建议研究方向】\n1. 大模型个性化（Personalized LLM）：通过角色扮演、用户行为数据挖掘与建模、上下文理解等方法，分析用户情感状态，提升模型的个性化回复能力。\n2. 面向语音交互的拟人化技术（Voice Agent）：优化大模型在语音对话场景的效果，提升大模型的拟人化水平，探索下一代端到端语音对话大模型的技术实现。\n3. 记忆管理与增强（Memory）：通过优化模型长上下文能力、设计记忆抽取与管理模块，提升系统的记忆能力。\n4. 基于LLM的RL（LLM-based RL）：通过强化学习，提升模型规划、决策、推理等能力。\n我们将提供充足的计算资源和良好的工作自由度，目标是产出有影响力的工作，解决业务实践中的问题。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n以大模型对话技术为核心，探索前沿技术问题。研究方向包括角色扮演、个性化对话、记忆管理，拟人化，数字人等，主要业务场景包括运营，招聘，销售，审核等。目标是构建覆盖多个场景的Agent系统，实现“技术驱动业务范式”的升级转变。\n【建议研究方向】\n1. 大模型个性化（Personalized LLM）：通过角色扮演、用户行为数据挖掘与建模、上下文理解等方法，分析用户情感状态，提升模型的个性化回复能力。\n2. 面向语音交互的拟人化技术（Voice Agent）：优化大模型在语音对话场景的效果，提升大模型的拟人化水平，探索下一代端到端语音对话大模型的技术实现。\n3. 记忆管理与增强（Memory）：通过优化模型长上下文能力、设计记忆抽取与管理模块，提升系统的记忆能力。\n4. 基于LLM的RL（LLM-based RL）：通过强化学习，提升模型规划、决策、推理等能力。\n我们将提供充足的计算资源和良好的工作自由度，目标是产出有影响力的工作，解决业务实践中的问题。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3396015151","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【行业大模型】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3396015151&jobShareType=1","duty":"【课题说明】\n大模型研发正从“人类数据时代”跨入“经验时代”，评估已然是大模型研发的重点和难点。具体而言，评估驱动的行业大模型研发下半场范式主要包括两方面内容：①行业核心问题定义和评估归因；②Post-Training多阶段协同的效果提升。本课题基于美团的本地生活业务，精选销售、履约、医药和客服四个代表性行业，旨在探索评估驱动的行业大模型研发的下半场范式。\n【建议研究方向】\n1.行业大模型通用评估方案探索。\n2.行业模型reward设计与探索。\n3.面向行业推理能力建设的通用自动化样本构建方法和评估归因方法。\n4.面向行业推理能力增强的通用强化训练方案。\n5.销售、履约、医药和客服行业大模型训练。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n大模型研发正从“人类数据时代”跨入“经验时代”，评估已然是大模型研发的重点和难点。具体而言，评估驱动的行业大模型研发下半场范式主要包括两方面内容：①行业核心问题定义和评估归因；②Post-Training多阶段协同的效果提升。本课题基于美团的本地生活业务，精选销售、履约、医药和客服四个代表性行业，旨在探索评估驱动的行业大模型研发的下半场范式。\n【建议研究方向】\n1.行业大模型通用评估方案探索。\n2.行业模型reward设计与探索。\n3.面向行业推理能力建设的通用自动化样本构建方法和评估归因方法。\n4.面向行业推理能力增强的通用强化训练方案。\n5.销售、履约、医药和客服行业大模型训练。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3396064381","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【多模态数字人】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3396064381&jobShareType=1","duty":"【课题说明】\n聚焦多模态数字人核心技术，以直播为应用场景，旨在突破其在真实感、智能交互、情感表达及多模态信息处理上的瓶颈。研发能自主执行复杂运营任务、展现丰富情感与高表现力，并与用户进行深度多模态内容互动的下一代数字人，革新直播行业运营模式与用户体验。\n【建议研究方向】\n1.智能运营Agent：研究数字人作为智能Agent，在直播前（策划、脚本、货盘）、中（场控、问答、促单）、后（复盘、再创）全流程承担运营职能。重点攻克基于多模态数据的智能决策、任务自动化及人机协同，提升直播运营效能。\n2.高表现力数字人生成驱动：探索高真实感、个性化数字人形象（外观、声音、风格）的快速生成与定制。重点研究大模型驱动的、与语音同步且富含细腻情感的表情、口型、动作的实时驱动，增强直播感染力。\n3.多模态内容生成和交互：研究理解用户多模态输入（文、语、图、视频）并进行深度互动。探索数字人自主生成动态多模态内容，丰富直播呈现，提升用户参与感。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n聚焦多模态数字人核心技术，以直播为应用场景，旨在突破其在真实感、智能交互、情感表达及多模态信息处理上的瓶颈。研发能自主执行复杂运营任务、展现丰富情感与高表现力，并与用户进行深度多模态内容互动的下一代数字人，革新直播行业运营模式与用户体验。\n【建议研究方向】\n1.智能运营Agent：研究数字人作为智能Agent，在直播前（策划、脚本、货盘）、中（场控、问答、促单）、后（复盘、再创）全流程承担运营职能。重点攻克基于多模态数据的智能决策、任务自动化及人机协同，提升直播运营效能。\n2.高表现力数字人生成驱动：探索高真实感、个性化数字人形象（外观、声音、风格）的快速生成与定制。重点研究大模型驱动的、与语音同步且富含细腻情感的表情、口型、动作的实时驱动，增强直播感染力。\n3.多模态内容生成和交互：研究理解用户多模态输入（文、语、图、视频）并进行深度互动。探索数字人自主生成动态多模态内容，丰富直播呈现，提升用户参与感。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3394739913","sourceKey":"meituan","company":"美团","title":"【北斗实习】广告大模型应用算法工程师-【广告创意生产】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3394739913&jobShareType=1","duty":"【课题说明】\n在广告场景中，优质精美的创意对用户的行为决策有显著正向影响，传统模式下商用级创意内容的制作门槛高、生产周期长，长尾商家通常难以负担其成本，而头腰部商家也难以做到个性化、高时效性的创意生产投放。\n本课题借助大模型的音、视、图、文等多模态理解、思考与生成能力，结合用户画像、商户/品特征、热点趋势等信息，探索实现低成本、个性化的商用级创意内容（如图文笔记、长视频）的生成技术。\n【建议研究方向】\n1.多模态深度思考：设计与实现多模态深度思考方案，优化模型对多源异构信息进行抽取筛选、加工整合、衍生创作的能力，提升创意内容生成的质量与多样性。\n2.开放问题的强化学习：针对无标准答案的开放问题（如笔记生成、剧本创作、素材选取等），设计与实现适配的奖励机制与策略，通过强化学习提升模型能力。\n3.创意生产Agent：参考人工生产中的不同角色分工合作流程，设计与实现创意生产的多agent协作框架，并通过线上效果反馈机制，闭环提升生产的效率与质量。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n在广告场景中，优质精美的创意对用户的行为决策有显著正向影响，传统模式下商用级创意内容的制作门槛高、生产周期长，长尾商家通常难以负担其成本，而头腰部商家也难以做到个性化、高时效性的创意生产投放。\n本课题借助大模型的音、视、图、文等多模态理解、思考与生成能力，结合用户画像、商户/品特征、热点趋势等信息，探索实现低成本、个性化的商用级创意内容（如图文笔记、长视频）的生成技术。\n【建议研究方向】\n1.多模态深度思考：设计与实现多模态深度思考方案，优化模型对多源异构信息进行抽取筛选、加工整合、衍生创作的能力，提升创意内容生成的质量与多样性。\n2.开放问题的强化学习：针对无标准答案的开放问题（如笔记生成、剧本创作、素材选取等），设计与实现适配的奖励机制与策略，通过强化学习提升模型能力。\n3.创意生产Agent：参考人工生产中的不同角色分工合作流程，设计与实现创意生产的多agent协作框架，并通过线上效果反馈机制，闭环提升生产的效率与质量。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3394452304","sourceKey":"meituan","company":"美团","title":"【北斗实习】广告大模型应用算法工程师-【智能IM】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3394452304&jobShareType=1","duty":"【课题说明】\n美团商家通过IM与用户交互帮助用户答疑，提升用户下单意愿，完成导购、客服、留资等任务。整体链路人工依赖率高。随着大模型技术的快速发展，基于大模型的智能外呼在提升电销覆盖率和转化率方面展现出极大潜力。\n本课题致力于将大模型技术和商家端的各项客服任务相结合，通过大模型能力赋能美团商家与用户交互过程，降低商家与客户交互的成本，提升商户的成单数量。\n【建议研究方向】\n1.基于多智能体的商家助手设计：设计基于大模型的多智能体交互方案，让模型在与用户交互过程中，能给有效识别用户意图，完成多轮交互。\n2.工具调用与任务分解：设计多工具调用框架，使商家助手能够动态组合调用业务API、业务数据库等工具，完成多种复杂任务。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n美团商家通过IM与用户交互帮助用户答疑，提升用户下单意愿，完成导购、客服、留资等任务。整体链路人工依赖率高。随着大模型技术的快速发展，基于大模型的智能外呼在提升电销覆盖率和转化率方面展现出极大潜力。\n本课题致力于将大模型技术和商家端的各项客服任务相结合，通过大模型能力赋能美团商家与用户交互过程，降低商家与客户交互的成本，提升商户的成单数量。\n【建议研究方向】\n1.基于多智能体的商家助手设计：设计基于大模型的多智能体交互方案，让模型在与用户交互过程中，能给有效识别用户意图，完成多轮交互。\n2.工具调用与任务分解：设计多工具调用框架，使商家助手能够动态组合调用业务API、业务数据库等工具，完成多种复杂任务。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3395998670","sourceKey":"meituan","company":"美团","title":"【北斗实习】广告大模型应用算法工程师-【智能销售】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3395998670&jobShareType=1","duty":"【课题说明】\n传统销售模式中，销售人员通过电销系统触达商户，对商户进行营销/运营触达，整体链路人工依赖率高。随着大模型技术的快速发展，基于大模型的智能外呼在提升电销覆盖率和转化率方面展现出极大潜力。\n本课题致力于将大模型技术和智能外呼任务相结合，优化美团智能外呼系统，增强其在复杂对话环境下的意图理解与灵活应对能力。力图实现更自然的语音交互、更精准的营销策略，以及更灵活的应答处理等。\n【建议研究方向】\n1.转化信号奖励建模：依托业务场景多轮对话的真实转化信号，构建商家画像、对话文本特征信号以及交互环境特征，预估对话的转化率，进而通过强化学习（DPO/GRPO/RLHF）引导模型营销话术生成。\n2.销售领域垂类大模型：通过收集多场景销售数据以及美团广告产品知识，通过continue-Pretraining构建垂类通用销售模型基座，支持多业务场景快速支持应用。\n3.Multi-Agent交互式外呼系统：通过构建任务规划、流程监督、对话营销等多个agent交互逻辑，在较低响应耗时条件下，实现最佳的电话沟通效果。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n传统销售模式中，销售人员通过电销系统触达商户，对商户进行营销/运营触达，整体链路人工依赖率高。随着大模型技术的快速发展，基于大模型的智能外呼在提升电销覆盖率和转化率方面展现出极大潜力。\n本课题致力于将大模型技术和智能外呼任务相结合，优化美团智能外呼系统，增强其在复杂对话环境下的意图理解与灵活应对能力。力图实现更自然的语音交互、更精准的营销策略，以及更灵活的应答处理等。\n【建议研究方向】\n1.转化信号奖励建模：依托业务场景多轮对话的真实转化信号，构建商家画像、对话文本特征信号以及交互环境特征，预估对话的转化率，进而通过强化学习（DPO/GRPO/RLHF）引导模型营销话术生成。\n2.销售领域垂类大模型：通过收集多场景销售数据以及美团广告产品知识，通过continue-Pretraining构建垂类通用销售模型基座，支持多业务场景快速支持应用。\n3.Multi-Agent交互式外呼系统：通过构建任务规划、流程监督、对话营销等多个agent交互逻辑，在较低响应耗时条件下，实现最佳的电话沟通效果。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3395994460","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【生成式推荐系统】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3395994460&jobShareType=1","duty":"【课题说明】\n传统的向量召回和深度学习推荐范式在深度交互、冷启动、长尾商品发现、多场景适配等方面仍存在诸多挑战。生成式推荐系统以大模型为核心，具备强大的内容理解、知识推理和个性化内容生成能力。通过将用户历史行为、上下文信息、多模态内容等深度融合，生成式推荐系统能够实现用户意图的主动理解、候选内容的生成与多场景下的精准推荐，极大提升用户体验和平台生态活力。\n【建议研究方向】\n1.生成式召回：研究基于大模型的生成式召回方法，实现以模型参数为载体的候选内容记忆与生成，突破传统召回技术的局限。\n2.多轮交互推荐技术：探索多轮用户引导与深度交互机制，实时理解用户意图变化，满足“千人千面”的个性化需求。\n3.推荐系统的可解释性与安全性：研究大模型驱动的推荐逻辑可解释性方法，提升用户对推荐决策的理解和信任。同时探索生成式推荐中的内容安全，保障推荐系统的合规性与用户体验。\n4.推荐智能体与复杂任务规划：构建具备推理、规划和自主决策能力的推荐智能体，支持跨领域、跨步骤的复杂任务推荐。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n传统的向量召回和深度学习推荐范式在深度交互、冷启动、长尾商品发现、多场景适配等方面仍存在诸多挑战。生成式推荐系统以大模型为核心，具备强大的内容理解、知识推理和个性化内容生成能力。通过将用户历史行为、上下文信息、多模态内容等深度融合，生成式推荐系统能够实现用户意图的主动理解、候选内容的生成与多场景下的精准推荐，极大提升用户体验和平台生态活力。\n【建议研究方向】\n1.生成式召回：研究基于大模型的生成式召回方法，实现以模型参数为载体的候选内容记忆与生成，突破传统召回技术的局限。\n2.多轮交互推荐技术：探索多轮用户引导与深度交互机制，实时理解用户意图变化，满足“千人千面”的个性化需求。\n3.推荐系统的可解释性与安全性：研究大模型驱动的推荐逻辑可解释性方法，提升用户对推荐决策的理解和信任。同时探索生成式推荐中的内容安全，保障推荐系统的合规性与用户体验。\n4.推荐智能体与复杂任务规划：构建具备推理、规划和自主决策能力的推荐智能体，支持跨领域、跨步骤的复杂任务推荐。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3395026635","sourceKey":"meituan","company":"美团","title":"【北斗实习】广告大模型算法工程师-【生成式广告】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3395026635&jobShareType=1","duty":"【课题说明】\n信息流广告系统一般采用“召回->粗排->精排->出价->拍卖”的多级漏斗架构，但各模块独立优化导致优化目标不一致，前链路会制约后链路上限，漏斗效率折损大。\n近年来，随着大模型和生成式技术的快速发展，其强大的表征能力和良好的Scaling性质也为广告系统提供了新的可能性。本研究旨在探索如何利用生成式技术重塑整个广告系统，通过一个端到端的生成式广告大模型完成所有决策，打破多级漏斗框架，打开模型决策空间，最大化平台收益。\n【建议研究方向】\n1.生成式广告大模型架构设计：基于前沿大模型（如时空Transformer、MLA、MoE等），设计适配广告场景的生成式决策框架，支持根据“用户行为、实时位置、商户出价”端到端生成最优的广告商家、展示创意、相应计费。\n2.多阶段的训练范式设计：借鉴LLM的分阶段训练技术（如PT、SFT、RLHF等），设计“基于海量交互的 pre-training 和 基于业务目标的 post-training ”的分阶段训练范式，提升广告大模型效果。\n3.广告大模型的Scaling规律探索：探索广告场景下，生成式大模型“算力->效果”的转化规律，驱动推广搜迭代范式实现由“人工设计迭代”到“算力堆叠迭代”的跃迁。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\n信息流广告系统一般采用“召回->粗排->精排->出价->拍卖”的多级漏斗架构，但各模块独立优化导致优化目标不一致，前链路会制约后链路上限，漏斗效率折损大。\n近年来，随着大模型和生成式技术的快速发展，其强大的表征能力和良好的Scaling性质也为广告系统提供了新的可能性。本研究旨在探索如何利用生成式技术重塑整个广告系统，通过一个端到端的生成式广告大模型完成所有决策，打破多级漏斗框架，打开模型决策空间，最大化平台收益。\n【建议研究方向】\n1.生成式广告大模型架构设计：基于前沿大模型（如时空Transformer、MLA、MoE等），设计适配广告场景的生成式决策框架，支持根据“用户行为、实时位置、商户出价”端到端生成最优的广告商家、展示创意、相应计费。\n2.多阶段的训练范式设计：借鉴LLM的分阶段训练技术（如PT、SFT、RLHF等），设计“基于海量交互的 pre-training 和 基于业务目标的 post-training ”的分阶段训练范式，提升广告大模型效果。\n3.广告大模型的Scaling规律探索：探索广告场景下，生成式大模型“算力->效果”的转化规律，驱动推广搜迭代范式实现由“人工设计迭代”到“算力堆叠迭代”的跃迁。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3394467312","sourceKey":"meituan","company":"美团","title":"【北斗实习】大模型应用算法工程师-【AI搜索 & Agent RL】","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3394467312&jobShareType=1","duty":"【课题说明】\nAgentic Search是以大模型为核心，具备自主感知、推理与行动能力的搜索新范式。它通过理解用户复杂意图，动态规划搜索路径，主动调用多种工具和数据源，持续优化结果推荐与交互体验。本课题旨在研究和构建面向美团App本地生活服务的Agentic Search系统，探索其在多轮对话、复杂任务分解、实时信息整合等场景下的关键技术与应用价值，推动本地生活智能搜索技术的创新升级。\n【建议研究方向】\n1.意图理解与任务分解：探索大模型在复杂用户需求下的多意图识别、任务分解、子任务规划能力，提升系统对复合型检索场景的适应性和响应能力。\n2.多轮工具调用技术研究：赋予LLM长链路的多轮工具调用能力，打造基于强化学习等前沿技术的LLM后训练方案，提升多轮调用时的精确性及用户的实际交互体验。\n3.增量学习训练技术探索：针对本地生活场景中数据不断更新的特点，运用增量学习技术，使 AI 搜索模型能够快速适应新数据。\n搜索结果可解释性提升：探索基于大模型内容深度理解与推理的可解释理由生成，增强用户对搜索结果的信任感和透明度。","requirements":"海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n【课题说明】\nAgentic Search是以大模型为核心，具备自主感知、推理与行动能力的搜索新范式。它通过理解用户复杂意图，动态规划搜索路径，主动调用多种工具和数据源，持续优化结果推荐与交互体验。本课题旨在研究和构建面向美团App本地生活服务的Agentic Search系统，探索其在多轮对话、复杂任务分解、实时信息整合等场景下的关键技术与应用价值，推动本地生活智能搜索技术的创新升级。\n【建议研究方向】\n1.意图理解与任务分解：探索大模型在复杂用户需求下的多意图识别、任务分解、子任务规划能力，提升系统对复合型检索场景的适应性和响应能力。\n2.多轮工具调用技术研究：赋予LLM长链路的多轮工具调用能力，打造基于强化学习等前沿技术的LLM后训练方案，提升多轮调用时的精确性及用户的实际交互体验。\n3.增量学习训练技术探索：针对本地生活场景中数据不断更新的特点，运用增量学习技术，使 AI 搜索模型能够快速适应新数据。\n搜索结果可解释性提升：探索基于大模型内容深度理解与推理的可解释理由生成，增强用户对搜索结果的信任感和透明度。\n\n任职要求\n海内外高校在校本科生（大三及以上）、硕士生及博士生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前1%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3392128388","sourceKey":"meituan","company":"美团","title":"大模型数据运营-音乐数据方向实习生","city":"北京市/成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3392128388&jobShareType=1","duty":"1. 依据规则对音乐生成、音乐理解数据做标注、对供应商数据做验收、对生成歌曲做评估，包含但不限于“流派、乐曲结构、乐节、调式、音调、配器、歌唱技巧、速度、语种”等音乐信息；\n2. 参与音乐生成、音乐理解模型的数据生产规则制定与迭代。","requirements":"1. 本科学历及以上；\n2. 乐理基础扎实，熟练使用表格、文档等办公软件；\n3. 能够连续实习 3 个月及以上，每周出勤至少 4 天。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 依据规则对音乐生成、音乐理解数据做标注、对供应商数据做验收、对生成歌曲做评估，包含但不限于“流派、乐曲结构、乐节、调式、音调、配器、歌唱技巧、速度、语种”等音乐信息；\n2. 参与音乐生成、音乐理解模型的数据生产规则制定与迭代。\n\n岗位基本要求\n1. 本科学历及以上；\n2. 乐理基础扎实，熟练使用表格、文档等办公软件；\n3. 能够连续实习 3 个月及以上，每周出勤至少 4 天。\n\n具备以下条件优先\n1. 音乐类专业，录音工程专业优先；\n2. 具有编曲、混音等音乐制作经验者优先；\n3. 对主观的音乐信息有客观/抽象评价的能力者优先；\n4. 对人工智能音乐技术感兴趣者优先。\n\n岗位亮点\n1. 你将加入优秀的团队，一起成长：团队高阶研发密度大，汇聚行业大牛，分享交流活动多；\n2. 你将一起参与前沿技术的探究：热门智能技术发展方向，未来拥有广阔的应用前景；\n3. 你将拥有快速成长的空间，一起见证技术落地的喜悦：部门业务处于快速发展阶段，应用场景广泛，业务落地场景丰富，复杂度高，挑战性大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3379054365","sourceKey":"meituan","company":"美团","title":"商业分析师实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3379054365&jobShareType=1","duty":"岗位职责:\n1. 基于业务，完善业务监控体系和分析体系，包括KPI指标体系、搭建分析框架，并进行核心指标监控；\n2. 深入业务，研究分析相关行业的标杆，诊断业务问题并提出策略建议；\n3. 与业务产品团队、运营团队密切配合，提供相关分析支持和决策支持。","requirements":"岗位要求:\n1. 具备出色的逻辑思维能力和快速的学习能力，乐于思考；\n2. 有互联网行业或线上营销行业相关数据分析、经营分析实习经验；\n3. 熟练使用sql进行数据查询，使用常用数据工具进行数据分析，数据模型探索；\n4. 具有良好的逻辑分析能力、沟通能力、团队合作意识；\n5. 业务敏感度强，自驱力强，具有良好的商业敏感度和数据分析技能。","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n岗位职责:\n1. 基于业务，完善业务监控体系和分析体系，包括KPI指标体系、搭建分析框架，并进行核心指标监控；\n2. 深入业务，研究分析相关行业的标杆，诊断业务问题并提出策略建议；\n3. 与业务产品团队、运营团队密切配合，提供相关分析支持和决策支持。\n\n岗位基本要求\n岗位要求:\n1. 具备出色的逻辑思维能力和快速的学习能力，乐于思考；\n2. 有互联网行业或线上营销行业相关数据分析、经营分析实习经验；\n3. 熟练使用sql进行数据查询，使用常用数据工具进行数据分析，数据模型探索；\n4. 具有良好的逻辑分析能力、沟通能力、团队合作意识；\n5. 业务敏感度强，自驱力强，具有良好的商业敏感度和数据分析技能。\n\n岗位亮点\n岗位亮点:\n美团本地生活商业化业务，覆盖外卖、到店餐饮、丽人医美、休闲娱乐等多行业变现，未来发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155429204","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】推理决策智能体技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155429204&jobShareType=1","duty":"本课题聚焦大模型在复杂场景下的高阶认知能力突破，面向真实需求构建具备自主推理与协作进化能力的智能系统。通过前沿算法创新与工业级场景验证，助力研究者攻克高度自适应智能体架构设计、复杂决策优化等关键技术难题。\n核心研究内容包括：\n1）构建复杂情境推理框架：开发能够处理模糊信息、进行合理假设并自主验证的决策系统，突破不完全数据下的逻辑闭环能力。\n2）建立多智能体协作范式：研究分层任务拆解机制与分布式决策架构，实现跨智能体的动态协调与效能优化。\n3）设计任务驱动进化机制：结合强化学习与反思模型，持续提升智能体在业务场景中的自主适应与问题排查能力。\n4）开发模型可解释性框架：创新推理过程可视化技术，建立决策依据追溯机制，显著降低模型幻觉风险。\n5）探索人机协同新形态：构建具备环境感知与交互进化能力的智能助手，推动大模型在真实场景的可靠落地。","requirements":"1）熟悉TensorFlow、PyTorch等深度学习框架、和主流编程语言、CUDA/Triton语言，具备扎实的深度学习理论基础。\n2）有扎实的大模型实践和研究能力，尤其是在推理和决策优化领域具有深刻的理解。\n3）发表过高水平论文（如NeurIPS, ICLR, ICML, ACL, EMNLP等）。\n加分项：\n1）有影响力的开源项目中做出过核心贡献，尤其是与大模型推理或多智能体协作相关的项目。\n2）具备复杂推理、自主执行能力的大模型系统，在业务场景上设计和落地经验。","description":"岗位职责\n本课题聚焦大模型在复杂场景下的高阶认知能力突破，面向真实需求构建具备自主推理与协作进化能力的智能系统。通过前沿算法创新与工业级场景验证，助力研究者攻克高度自适应智能体架构设计、复杂决策优化等关键技术难题。\n核心研究内容包括：\n1）构建复杂情境推理框架：开发能够处理模糊信息、进行合理假设并自主验证的决策系统，突破不完全数据下的逻辑闭环能力。\n2）建立多智能体协作范式：研究分层任务拆解机制与分布式决策架构，实现跨智能体的动态协调与效能优化。\n3）设计任务驱动进化机制：结合强化学习与反思模型，持续提升智能体在业务场景中的自主适应与问题排查能力。\n4）开发模型可解释性框架：创新推理过程可视化技术，建立决策依据追溯机制，显著降低模型幻觉风险。\n5）探索人机协同新形态：构建具备环境感知与交互进化能力的智能助手，推动大模型在真实场景的可靠落地。\n\n任职要求\n1）熟悉TensorFlow、PyTorch等深度学习框架、和主流编程语言、CUDA/Triton语言，具备扎实的深度学习理论基础。\n2）有扎实的大模型实践和研究能力，尤其是在推理和决策优化领域具有深刻的理解。\n3）发表过高水平论文（如NeurIPS, ICLR, ICML, ACL, EMNLP等）。\n加分项：\n1）有影响力的开源项目中做出过核心贡献，尤其是与大模型推理或多智能体协作相关的项目。\n2）具备复杂推理、自主执行能力的大模型系统，在业务场景上设计和落地经验。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155431042","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】音频内容生成算法研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155431042&jobShareType=1","duty":"在内容生成领域，音频生成逐渐成为热门研究方向，具有广阔的应用前景和研究价值。本课题专注于音频内容生成方向，包括但不限于：\n1）音视频联合生成：探索如何使模型在生成过程中有效地结合文本、语音和图像信息，提升生成结果的相关性和自然度。\n2）音频数据处理与融合：研究音频数据的预处理和特征提取技术，以优化生成模型的输入输出。\n3）多模态生成模型的性能评估：设计自动化评估方法，量化多模态生成模型在下游任务中的表现。","requirements":"1）熟悉常见的多模态大模型架构。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）高星开源项目，社区关注度高。\n2）发表过高水平论文，如 ICLR、NeurIPS、ICML、CVPR 等。","description":"岗位职责\n在内容生成领域，音频生成逐渐成为热门研究方向，具有广阔的应用前景和研究价值。本课题专注于音频内容生成方向，包括但不限于：\n1）音视频联合生成：探索如何使模型在生成过程中有效地结合文本、语音和图像信息，提升生成结果的相关性和自然度。\n2）音频数据处理与融合：研究音频数据的预处理和特征提取技术，以优化生成模型的输入输出。\n3）多模态生成模型的性能评估：设计自动化评估方法，量化多模态生成模型在下游任务中的表现。\n\n任职要求\n1）熟悉常见的多模态大模型架构。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）高星开源项目，社区关注度高。\n2）发表过高水平论文，如 ICLR、NeurIPS、ICML、CVPR 等。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155435203","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】虚拟人交互前沿路线研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155435203&jobShareType=1","duty":"随着多模态大模型的发展，虚拟人交互也迎来智能化和拟人化的升级。 传统的2D虚拟人主要专注于语音与嘴型对齐，而大模型时代的虚拟人需具备多模感知和推理的能力，视觉生成需具备高度拟人化。课题研究内容包括但不限于：\n1）基于多模态大模型构建端到端交互虚拟人模型，实现智能双工交互，人、物、场景交互，高度拟人化等能力。\n2）Human Video Model：构建具备高质量人脸、人体、人物交互生成能力的虚拟人基座。","requirements":"1）熟悉多模态大模型、2D虚拟人、视频生成等相关研究进展。\n2）熟悉PyTorch，有充分的动手实践经验。\n加分项：\n1）社区影响力：有多模态大模型、视频生成、虚拟人相关研究和实习经历，有影响力的开源项目中做出过核心贡献。\n2）学术影响力：发表过高水平论文（如ICLR、CVPR、ICCV等），有相关竞赛经历并取得名次。","description":"岗位职责\n随着多模态大模型的发展，虚拟人交互也迎来智能化和拟人化的升级。 传统的2D虚拟人主要专注于语音与嘴型对齐，而大模型时代的虚拟人需具备多模感知和推理的能力，视觉生成需具备高度拟人化。课题研究内容包括但不限于：\n1）基于多模态大模型构建端到端交互虚拟人模型，实现智能双工交互，人、物、场景交互，高度拟人化等能力。\n2）Human Video Model：构建具备高质量人脸、人体、人物交互生成能力的虚拟人基座。\n\n任职要求\n1）熟悉多模态大模型、2D虚拟人、视频生成等相关研究进展。\n2）熟悉PyTorch，有充分的动手实践经验。\n加分项：\n1）社区影响力：有多模态大模型、视频生成、虚拟人相关研究和实习经历，有影响力的开源项目中做出过核心贡献。\n2）学术影响力：发表过高水平论文（如ICLR、CVPR、ICCV等），有相关竞赛经历并取得名次。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155424457","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】图像生成大模型技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155424457&jobShareType=1","duty":"在AIGC大模型的RLHF阶段，奖励模型（Reward Models）通过提供精准的奖励反馈来调整模型优化方向，以提升图像生成的质感与美感，从而增强整体视觉呈现效果。同时，随着模型参数规模的不断增加，亟需从模型架构层面探讨更优的生成策略。课题研究内容包括但不限于：\n1）多维度图像奖励模型的设计。\n2）DiT框架的优化，探索性能与推理效率的极限。\n3）图像生成范式的探索，系统性验证AR或AR+Diffusion方案的优缺点，以迈向更大规模的生成模型。","requirements":"1）熟悉扩散模型研究进展。\n2）熟悉PyTorch，能快速开展实验。\n加分项：\n1）有图像/视频生成大模型研究经验，或者在相关开源项目中做出过核心贡献。\n2）对AIGC的训练与推理优化有实践经验。\n3）在计算机视觉、多媒体、人工智能的权威期刊或会议上发表过视觉生成相关的论文专著，或者在重要算法比赛中取得过优秀名次。","description":"岗位职责\n在AIGC大模型的RLHF阶段，奖励模型（Reward Models）通过提供精准的奖励反馈来调整模型优化方向，以提升图像生成的质感与美感，从而增强整体视觉呈现效果。同时，随着模型参数规模的不断增加，亟需从模型架构层面探讨更优的生成策略。课题研究内容包括但不限于：\n1）多维度图像奖励模型的设计。\n2）DiT框架的优化，探索性能与推理效率的极限。\n3）图像生成范式的探索，系统性验证AR或AR+Diffusion方案的优缺点，以迈向更大规模的生成模型。\n\n任职要求\n1）熟悉扩散模型研究进展。\n2）熟悉PyTorch，能快速开展实验。\n加分项：\n1）有图像/视频生成大模型研究经验，或者在相关开源项目中做出过核心贡献。\n2）对AIGC的训练与推理优化有实践经验。\n3）在计算机视觉、多媒体、人工智能的权威期刊或会议上发表过视觉生成相关的论文专著，或者在重要算法比赛中取得过优秀名次。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155419418","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】基于原生语音大模型的情感陪伴智能体","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155419418&jobShareType=1","duty":"该课题聚焦于利用原生语音大模型构建情感陪伴 Agent，通过实时全双工交互，精准理解和感知用户情绪，凭借高情商为用户提供极具价值的回复，旨在为用户打造温暖、贴心且高度智能的情感陪伴体验。​研究内容：​\n1）模型优化：参与优化原生语音多模态大模型，通过改进Speech Tokenizer和文本-语音的对齐机制等措施，提升模型对语音中包含的语义以及声学信息的实时理解与处理能力，增强其对用户情绪的精准识别。​\n2）交互设计：设计高效、自然的全双工交互机制，确保 Agent 与用户之间的交流流畅且符合日常沟通习惯，提高交互的实时性与稳定性。​\n3）情商塑造：运用先进技术手段，赋予 Agent 高情商特质，使其能够根据用户情绪做出恰当、暖心且富有智慧的回应，提升用户情感体验。​\n4）数据构建：收集、整理、合成与情感陪伴相关的语音对话数据，为模型训练与优化提供高质量的数据支持，推动模型性能持续提升。​","requirements":"1）熟悉LLM、Speech Codec、NLP Dialog、语音（ASR / TTS）、情感分析等相关领域，对至少一个方向有深入研究，并有实际项目经验，能够将理论知识应用于实践。​\n2）熟练掌握 Python 等编程语言，具备良好的编程习惯与代码能力，熟悉 Linux 开发环境。​\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。​\n加分项：​\n1）曾在SpeechLM、Speech Codec、NLP Dialog等相关的开源项目中做出突出贡献。​\n2）曾在上述领域中发表过高水平论文者优先考虑。","description":"岗位职责\n该课题聚焦于利用原生语音大模型构建情感陪伴 Agent，通过实时全双工交互，精准理解和感知用户情绪，凭借高情商为用户提供极具价值的回复，旨在为用户打造温暖、贴心且高度智能的情感陪伴体验。​研究内容：​\n1）模型优化：参与优化原生语音多模态大模型，通过改进Speech Tokenizer和文本-语音的对齐机制等措施，提升模型对语音中包含的语义以及声学信息的实时理解与处理能力，增强其对用户情绪的精准识别。​\n2）交互设计：设计高效、自然的全双工交互机制，确保 Agent 与用户之间的交流流畅且符合日常沟通习惯，提高交互的实时性与稳定性。​\n3）情商塑造：运用先进技术手段，赋予 Agent 高情商特质，使其能够根据用户情绪做出恰当、暖心且富有智慧的回应，提升用户情感体验。​\n4）数据构建：收集、整理、合成与情感陪伴相关的语音对话数据，为模型训练与优化提供高质量的数据支持，推动模型性能持续提升。​\n\n任职要求\n1）熟悉LLM、Speech Codec、NLP Dialog、语音（ASR / TTS）、情感分析等相关领域，对至少一个方向有深入研究，并有实际项目经验，能够将理论知识应用于实践。​\n2）熟练掌握 Python 等编程语言，具备良好的编程习惯与代码能力，熟悉 Linux 开发环境。​\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。​\n加分项：​\n1）曾在SpeechLM、Speech Codec、NLP Dialog等相关的开源项目中做出突出贡献。​\n2）曾在上述领域中发表过高水平论文者优先考虑。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155393936","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大模型预训练数据构建理论与算法研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155393936&jobShareType=1","duty":"本课题研究方向包括但不限于：\n1）构建端到端的网页文本内容提取系统，针对网络数据的复杂性，从系统效率和模型效果角度持续优化内容提取算法，迭代生产标准。\n2）设计预训练数据的全局质量优化和治理方案，优化全局采样策略、隐私保护和安全合规，提升基座模型训练效率和最终效果。\n3）建设多模态交错数据处理链路，通过数据分析和配比实验等手段优化多模态数据质量和多样性，支撑多模态大模型数据需求。\n4）推动数据驱动的模型性能突破。\n5）负责千亿级网页的大规模处理和万亿级token数据生产，通过分布式计算、模型量化及显存优化的方式提升数据处理和生产效率。","requirements":"1）计算机科学、数据科学、自然语言处理等相关专业，具备大模型相关背景，在相关领域有深入研究经历并有实际论文产出或项目经验。\n2）扎实的编程功底，熟练掌握TensorFlow/PyTorch/Megatron等深度学习框架，熟悉Java/C++等编程语言；熟练掌握大数据处理工具，如Spark、Flink、Ray等。\n3）熟悉大模型训练流程，熟悉Transformer模型结构，对GPT/LLAMA/MoE等模型架构有深入了解。\n加分项：\n1）有大模型预训练相关数据构建和处理项目经验者优先。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\n本课题研究方向包括但不限于：\n1）构建端到端的网页文本内容提取系统，针对网络数据的复杂性，从系统效率和模型效果角度持续优化内容提取算法，迭代生产标准。\n2）设计预训练数据的全局质量优化和治理方案，优化全局采样策略、隐私保护和安全合规，提升基座模型训练效率和最终效果。\n3）建设多模态交错数据处理链路，通过数据分析和配比实验等手段优化多模态数据质量和多样性，支撑多模态大模型数据需求。\n4）推动数据驱动的模型性能突破。\n5）负责千亿级网页的大规模处理和万亿级token数据生产，通过分布式计算、模型量化及显存优化的方式提升数据处理和生产效率。\n\n任职要求\n1）计算机科学、数据科学、自然语言处理等相关专业，具备大模型相关背景，在相关领域有深入研究经历并有实际论文产出或项目经验。\n2）扎实的编程功底，熟练掌握TensorFlow/PyTorch/Megatron等深度学习框架，熟悉Java/C++等编程语言；熟练掌握大数据处理工具，如Spark、Flink、Ray等。\n3）熟悉大模型训练流程，熟悉Transformer模型结构，对GPT/LLAMA/MoE等模型架构有深入了解。\n加分项：\n1）有大模型预训练相关数据构建和处理项目经验者优先。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155414459","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】Operator 智能体方向算法研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155414459&jobShareType=1","duty":"随着大模型与生成式 AI 技术的快速发展，在多模态和复杂场景下让 Agent 具备更强大的决策和执行能力成为未来的重要趋势。OpenAI Operator 通过结合强化学习的多步决策机制与大模型的理解、推理优势，可在多种任务场景（如 Computer Use、网页浏览等）中实现高效且灵活的自动化决策和任务执行。本课题将聚焦多样化业务场景和复杂环境下的自适应策略设计、规划与推理，进一步提升 Agent 在真实应用中的表现。\n主要研究内容包括但不限于：\n1) 多模态与多步决策：设计并构建包含多模态信息、计算机交互、网络搜索、函数调用等多维度的复杂环境，研究如何利用端到端强化学习来进行多步决策，从而完成更具挑战的任务。\n2) 策略学习与优化：在多种强化学习算法（如 PPO、GRPO 等）的框架下，探索高效的策略优化方法，为 Operator Agent 提供强大的决策和执行能力。\n3) 规划与推理：借助大模型的知识与推理能力，设计可解释的多步规划算法；研究如何与外部工具或知识库交互，以扩展 Agent 的能力边界并提升其在真实环境中的自动化决策表现。","requirements":"1）熟悉强化学习领域常用算法及理论基础（如 DQN、Policy Gradient、PPO、GRPO 等。\n2）熟练掌握至少一门编程语言（如 Python、Java），熟悉 Linux 环境。\n3）具备深度学习框架（如 PyTorch、TensorFlow）实际项目经验；了解大模型或分布式训练框架（Megatron、DeepSpeed 等）者优先。\n4）对大模型在 Agent 规划、推理中的作用有浓厚兴趣，对 LLM + RL 的前沿研究有基本认识。\n5）具备良好的问题分析和解决能力，对新技术保持学习和探索的热情。\n加分项：\n1）在 NeurIPS、ICLR、ICML、ACL、EMNLP 等相关领域高水平期刊/会议发表论文或在有影响力的开源项目中做出核心贡献。\n2）在多 Agent、层级强化学习或多模态融合等领域有深入研究或项目经验者优先。\n3）具备 General Agent 使用经验（如 OpenAI Operator、Manus AI 等）者优先。","description":"岗位职责\n随着大模型与生成式 AI 技术的快速发展，在多模态和复杂场景下让 Agent 具备更强大的决策和执行能力成为未来的重要趋势。OpenAI Operator 通过结合强化学习的多步决策机制与大模型的理解、推理优势，可在多种任务场景（如 Computer Use、网页浏览等）中实现高效且灵活的自动化决策和任务执行。本课题将聚焦多样化业务场景和复杂环境下的自适应策略设计、规划与推理，进一步提升 Agent 在真实应用中的表现。\n主要研究内容包括但不限于：\n1) 多模态与多步决策：设计并构建包含多模态信息、计算机交互、网络搜索、函数调用等多维度的复杂环境，研究如何利用端到端强化学习来进行多步决策，从而完成更具挑战的任务。\n2) 策略学习与优化：在多种强化学习算法（如 PPO、GRPO 等）的框架下，探索高效的策略优化方法，为 Operator Agent 提供强大的决策和执行能力。\n3) 规划与推理：借助大模型的知识与推理能力，设计可解释的多步规划算法；研究如何与外部工具或知识库交互，以扩展 Agent 的能力边界并提升其在真实环境中的自动化决策表现。\n\n任职要求\n1）熟悉强化学习领域常用算法及理论基础（如 DQN、Policy Gradient、PPO、GRPO 等。\n2）熟练掌握至少一门编程语言（如 Python、Java），熟悉 Linux 环境。\n3）具备深度学习框架（如 PyTorch、TensorFlow）实际项目经验；了解大模型或分布式训练框架（Megatron、DeepSpeed 等）者优先。\n4）对大模型在 Agent 规划、推理中的作用有浓厚兴趣，对 LLM + RL 的前沿研究有基本认识。\n5）具备良好的问题分析和解决能力，对新技术保持学习和探索的热情。\n加分项：\n1）在 NeurIPS、ICLR、ICML、ACL、EMNLP 等相关领域高水平期刊/会议发表论文或在有影响力的开源项目中做出核心贡献。\n2）在多 Agent、层级强化学习或多模态融合等领域有深入研究或项目经验者优先。\n3）具备 General Agent 使用经验（如 OpenAI Operator、Manus AI 等）者优先。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153985521","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】长周期人机协作能力探索和评测","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153985521&jobShareType=1","duty":"大模型的语言理解与生成能力标志着基于人类语言的人机交互接口接近成熟。通过agent框架拓展系统环境适应力，结合推理技术突破（如o1/R1）强化中枢决策能力，内外协同将加速实现长周期人机协作，提升生产力。本课题希望逐步实现长周期人机协作所需的大模型agent能力，并解决其中涉及的模型训练和评估问题。研究内容包括但不限于：\n1）长周期人机协作所涉及的模型能力拆解。\n2）针对长周期协作所涉及的具体能力构建agent框架。\n3）基于能力拆解建设相关的评测评估方案。\n4）通过模型微调等手段优化相应的模型能力。","requirements":"1）熟悉大模型相关的推理、训练框架，有较强的工程实践能力和经验。\n2）有一定的学术研究背景，对前沿技术保持好奇心，学习能力和自驱力强。\n加分项：\n1）在有影响力的开源项目中做出核心贡献。\n2）发表过高质量学术论文。","description":"岗位职责\n大模型的语言理解与生成能力标志着基于人类语言的人机交互接口接近成熟。通过agent框架拓展系统环境适应力，结合推理技术突破（如o1/R1）强化中枢决策能力，内外协同将加速实现长周期人机协作，提升生产力。本课题希望逐步实现长周期人机协作所需的大模型agent能力，并解决其中涉及的模型训练和评估问题。研究内容包括但不限于：\n1）长周期人机协作所涉及的模型能力拆解。\n2）针对长周期协作所涉及的具体能力构建agent框架。\n3）基于能力拆解建设相关的评测评估方案。\n4）通过模型微调等手段优化相应的模型能力。\n\n任职要求\n1）熟悉大模型相关的推理、训练框架，有较强的工程实践能力和经验。\n2）有一定的学术研究背景，对前沿技术保持好奇心，学习能力和自驱力强。\n加分项：\n1）在有影响力的开源项目中做出核心贡献。\n2）发表过高质量学术论文。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3154001160","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】多模态融合及多模态实时交互算法研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3154001160&jobShareType=1","duty":"大语言模型（LLM）最近取得的突破极大地加速了多模态大语言模型（MLLM）的发展。全模态多模态大语言模型（Omni-MLLM）通过融入如视频、音频等额外的非语言模态，拓展了多模态大语言模型的能力，从而有助于更全面、多维度地理解各种模态，提供更强的智能以及更智能的交互模式。研究方向包括不限于：\n1) 多模态表征高效对齐研究：研究如何在统一模型架构下提取并共享视觉、语音、语言等模态的特征；探索基于对比学习、自监督学习的方法，优化多模态对齐过程；针对视频、音频等数据，研究时间序列信息的对齐技巧。\n2) 多模态知识迁移与涌现能力研究：研究知识在不同模态间的迁移规律，激发模型在跨模态任务中的涌现能力，实现对未见任务的泛化。\n3) 多模态融合：探索统一的全模态大模型框架，研究高效全模态预训练技术，探索跨模态数据上的scaling law和智能涌现能力。使之能够高效处理文本、音频、图像和视频输入的任意组合，并生成涵盖文本、音频和图像等多种模态的输出。\n4） 实时多模态交互：探索高效的多模态智能交互技术，增强系统在多模场景下的智能，提升人机实时音视频交互体验。","requirements":"1）对CV、NLP、语音等多模态相关领域有深入的理解，在其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）对多模态大模型有深入研究且有实际训练经验者优先。\n3）发表过高水平论文，如 ICLR、NeurIPS、ICML、CVPR 等。","description":"岗位职责\n大语言模型（LLM）最近取得的突破极大地加速了多模态大语言模型（MLLM）的发展。全模态多模态大语言模型（Omni-MLLM）通过融入如视频、音频等额外的非语言模态，拓展了多模态大语言模型的能力，从而有助于更全面、多维度地理解各种模态，提供更强的智能以及更智能的交互模式。研究方向包括不限于：\n1) 多模态表征高效对齐研究：研究如何在统一模型架构下提取并共享视觉、语音、语言等模态的特征；探索基于对比学习、自监督学习的方法，优化多模态对齐过程；针对视频、音频等数据，研究时间序列信息的对齐技巧。\n2) 多模态知识迁移与涌现能力研究：研究知识在不同模态间的迁移规律，激发模型在跨模态任务中的涌现能力，实现对未见任务的泛化。\n3) 多模态融合：探索统一的全模态大模型框架，研究高效全模态预训练技术，探索跨模态数据上的scaling law和智能涌现能力。使之能够高效处理文本、音频、图像和视频输入的任意组合，并生成涵盖文本、音频和图像等多种模态的输出。\n4） 实时多模态交互：探索高效的多模态智能交互技术，增强系统在多模场景下的智能，提升人机实时音视频交互体验。\n\n任职要求\n1）对CV、NLP、语音等多模态相关领域有深入的理解，在其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）对多模态大模型有深入研究且有实际训练经验者优先。\n3）发表过高水平论文，如 ICLR、NeurIPS、ICML、CVPR 等。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155408656","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】通用强化学习研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155408656&jobShareType=1","duty":"RL 技术和 Reasoning 技术是大模型处理各项复杂任务的核心。本课题聚焦于利用上述技术，构建能够应对多目标优化、长期规划和不确定性的智能决策系统。\n主要研究内容包括但不限于：\n1）多层次强化学习设计：研究 Hierarchical RL 与 LLM 的结合方法，构建能够处理抽象策略与具体执行的多层次决策系统；探索如何将复杂的系统任务分解为可管理的子任务，并能找到准确稠密的反馈信号，构建 Local RM 和 Global RM，进而完成可依赖和全局的优化。\n2）Reasoning 技术：针对不同的任务，能对 Reasoning 过程的 Token Budget、Reasoning 路径等，有稳定可控的方式，且能实现任务自适应。\n3）RL & Reasoning Scaling Law：探索高效的 RL Scaling 技术和 Test Time Scaling 技术，不断提升模型能力，且能兼顾探索利用和 Compute Cost。","requirements":"1）计算机科学、人工智能、机器学习或相关专业背景。\n2）熟练掌握 Python，具备高效实现和优化强化学习算法的能力。\n3）扎实的强化学习理论基础，熟悉分层强化学习、多智能体强化学习、贝叶斯强化学习等高级算法框架。\n4）熟悉 LLM 及其与 RL 结合的前沿技术。\n5）熟悉 Reasoning 相关技术。\n加分项：\n1）在NeurIPS、ICLR、ICML等顶级会议发表过 RL 或决策系统相关论文。\n2）参与过大规模 RL 系统的实际部署，并解决过生产环境中的稳定性和效率问题。","description":"岗位职责\nRL 技术和 Reasoning 技术是大模型处理各项复杂任务的核心。本课题聚焦于利用上述技术，构建能够应对多目标优化、长期规划和不确定性的智能决策系统。\n主要研究内容包括但不限于：\n1）多层次强化学习设计：研究 Hierarchical RL 与 LLM 的结合方法，构建能够处理抽象策略与具体执行的多层次决策系统；探索如何将复杂的系统任务分解为可管理的子任务，并能找到准确稠密的反馈信号，构建 Local RM 和 Global RM，进而完成可依赖和全局的优化。\n2）Reasoning 技术：针对不同的任务，能对 Reasoning 过程的 Token Budget、Reasoning 路径等，有稳定可控的方式，且能实现任务自适应。\n3）RL & Reasoning Scaling Law：探索高效的 RL Scaling 技术和 Test Time Scaling 技术，不断提升模型能力，且能兼顾探索利用和 Compute Cost。\n\n任职要求\n1）计算机科学、人工智能、机器学习或相关专业背景。\n2）熟练掌握 Python，具备高效实现和优化强化学习算法的能力。\n3）扎实的强化学习理论基础，熟悉分层强化学习、多智能体强化学习、贝叶斯强化学习等高级算法框架。\n4）熟悉 LLM 及其与 RL 结合的前沿技术。\n5）熟悉 Reasoning 相关技术。\n加分项：\n1）在NeurIPS、ICLR、ICML等顶级会议发表过 RL 或决策系统相关论文。\n2）参与过大规模 RL 系统的实际部署，并解决过生产环境中的稳定性和效率问题。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155417212","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】Post-training 前沿算法研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155417212&jobShareType=1","duty":"Post-training是联结大模型通用知识和人类偏好的桥梁，在规范知识输出、提升推理能力、对齐人类偏好等方面起到了关键作用。本课题专注于大模型Post-training相关前沿算法研究，包括但不限于：\n1）训练机制设计和优化：包括数据建设、指令微调，人类偏好和安全对齐，奖励模型、强化学习及效果评估等方向，优化模型文本创作、逻辑推理、指令遵循、代码生成、工具调用等能力，提升模型可控性和安全性。\n2）Post-training前沿研究：面向下一代推理基座的架构设计，test-time compute训练范式，思维链学习，多智能体和自博弈强化学习，提升模型的复杂任务处理能力和智能水平。","requirements":"1）熟悉NLP、LLM、RL等领域，在一个或多个相关领域有深入研究经历并有实际论文产出或项目经验。\n2）熟悉大模型算法研究所需的相关编程语言、工具、算法等，如Python、C++等编程语言、Megatron等训练框架、DPO、PPO等相关算法。\n3）具备独立开展科学研究和实验的能力，对大模型相关技术有浓厚兴趣，具备强烈的进取心、求知欲，热衷于追求行业顶尖的技术创新。\n加分项：\n1）有大模型一线研究和实践经验，在大模型领域发表过高影响力论文或主导/参与过知名开源项目者优先。\n2）发表过高影响力论文优先（如ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\nPost-training是联结大模型通用知识和人类偏好的桥梁，在规范知识输出、提升推理能力、对齐人类偏好等方面起到了关键作用。本课题专注于大模型Post-training相关前沿算法研究，包括但不限于：\n1）训练机制设计和优化：包括数据建设、指令微调，人类偏好和安全对齐，奖励模型、强化学习及效果评估等方向，优化模型文本创作、逻辑推理、指令遵循、代码生成、工具调用等能力，提升模型可控性和安全性。\n2）Post-training前沿研究：面向下一代推理基座的架构设计，test-time compute训练范式，思维链学习，多智能体和自博弈强化学习，提升模型的复杂任务处理能力和智能水平。\n\n任职要求\n1）熟悉NLP、LLM、RL等领域，在一个或多个相关领域有深入研究经历并有实际论文产出或项目经验。\n2）熟悉大模型算法研究所需的相关编程语言、工具、算法等，如Python、C++等编程语言、Megatron等训练框架、DPO、PPO等相关算法。\n3）具备独立开展科学研究和实验的能力，对大模型相关技术有浓厚兴趣，具备强烈的进取心、求知欲，热衷于追求行业顶尖的技术创新。\n加分项：\n1）有大模型一线研究和实践经验，在大模型领域发表过高影响力论文或主导/参与过知名开源项目者优先。\n2）发表过高影响力论文优先（如ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155423439","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】高拟人对话智能体技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155423439&jobShareType=1","duty":"课题目标是在提升工具调用、规划、记忆等基本能力之外，探索高度拟人，具备环境感知，知识遵循，思考决策能力，同时能够以稳定的人设和对话风格进行人机交互，最终完成对话任务的复杂智能体或多智能体。研究内容：\n1）研究智能体推理框架与各项基本能力的优化建模方法。通过多智能体架构与思维链设计，合成数据构造方法，大模型微调、强化等后训练方法的创新，实现智能体交互效果的提升。\n2）研究智能体快速适应具体应用领域要求的建模方法。通过挖掘领域关键知识与决策相关信号，设计依靠领域专家的主动学习范式，构建与人工偏好和流程规则对齐的建模方案，打造低成本迁移的拟人智能体。\n3）研究智能体情商和智商优化的自学习方法。结合应用需求设计奖励模型，通过强化学习等方法迭代智能体在意图理解和推测、情绪感知、主动服务、共情表达、语言风格等方面的表现，提升用户交互的满意度。","requirements":"1）对大模型、智能体、人机对话等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）有过任务型对话系统、强化学习、知识图谱、情感计算等方面的经验。\n3）在国际会议发表过高水平论文。\n4）关注行业应用动态。","description":"岗位职责\n课题目标是在提升工具调用、规划、记忆等基本能力之外，探索高度拟人，具备环境感知，知识遵循，思考决策能力，同时能够以稳定的人设和对话风格进行人机交互，最终完成对话任务的复杂智能体或多智能体。研究内容：\n1）研究智能体推理框架与各项基本能力的优化建模方法。通过多智能体架构与思维链设计，合成数据构造方法，大模型微调、强化等后训练方法的创新，实现智能体交互效果的提升。\n2）研究智能体快速适应具体应用领域要求的建模方法。通过挖掘领域关键知识与决策相关信号，设计依靠领域专家的主动学习范式，构建与人工偏好和流程规则对齐的建模方案，打造低成本迁移的拟人智能体。\n3）研究智能体情商和智商优化的自学习方法。结合应用需求设计奖励模型，通过强化学习等方法迭代智能体在意图理解和推测、情绪感知、主动服务、共情表达、语言风格等方面的表现，提升用户交互的满意度。\n\n任职要求\n1）对大模型、智能体、人机对话等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）有过任务型对话系统、强化学习、知识图谱、情感计算等方面的经验。\n3）在国际会议发表过高水平论文。\n4）关注行业应用动态。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3155412531","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】语音基座大模型前沿探索","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155412531&jobShareType=1","duty":"语音基座大模型是下一代语音算法的基础，也是多模态大模型研究的重要组成部分。本课题研究方向包括不限于：\n1）预训练方法研究：设计预训练任务，使训练可大规模扩展，且能够学习到丰富的知识，使得模型同时具备强大的理解和生成能力，进一步实现能力的涌现。\n2）tokenizer 优化：探索同时适用于理解和生成任务、兼顾学习效率和效果的tokenizer。\n3）泛音频理解：对语音理解之外，探索更广泛的音频（如音乐、环境声）理解能力，以及基于 reasoning 的理解能力。\n4) token2wav：与基座大模型配合，实现高效、高质量的语音/音频生成。\n5) post-training：探索基于 SFT 和 RL 的后训练策略，激活基座模型的理解和生成能力，实现通用的音频能力，并具备强表现力、多风格、多语种、多音色的能力。","requirements":"1）对语音、NLP、CV等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）对大模型有深入研究且有实际训练经验者优先。\n3）发表过高水平论文。","description":"岗位职责\n语音基座大模型是下一代语音算法的基础，也是多模态大模型研究的重要组成部分。本课题研究方向包括不限于：\n1）预训练方法研究：设计预训练任务，使训练可大规模扩展，且能够学习到丰富的知识，使得模型同时具备强大的理解和生成能力，进一步实现能力的涌现。\n2）tokenizer 优化：探索同时适用于理解和生成任务、兼顾学习效率和效果的tokenizer。\n3）泛音频理解：对语音理解之外，探索更广泛的音频（如音乐、环境声）理解能力，以及基于 reasoning 的理解能力。\n4) token2wav：与基座大模型配合，实现高效、高质量的语音/音频生成。\n5) post-training：探索基于 SFT 和 RL 的后训练策略，激活基座模型的理解和生成能力，实现通用的音频能力，并具备强表现力、多风格、多语种、多音色的能力。\n\n任职要求\n1）对语音、NLP、CV等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）对大模型有深入研究且有实际训练经验者优先。\n3）发表过高水平论文。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153872809","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大语言模型预训练结构和策略","city":"北京市/香港特别行政区/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153872809&jobShareType=1","duty":"探索下一代大模型预训练范式，从模型结构、训练策略、数据策略、算力利用率等角度切入，打造具有更强能力和更高潜力的基座模型。\n1）设计更高效的模型结构，提高给定数据量、计算量、硬件型号、输出序列长度等约束下的模型能力，如长序列能力、记忆能力等。\n2）探索更科学的训练策略，对影响training dynamic的关键变量（如学习率、batchsize、初始化等）形成更科学的认知，探索更适合大模型的optimizer等。\n3）研究模型结构和数据的耦合关系，优化分阶段训练范式。\n4）结合MLsys解决大规模训练中遇到的卡点问题，实现算法和工程联合设计。","requirements":"1）熟悉NLP、LLM、MLsys、Optimization、OR、Control、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉Pytorch、 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\n探索下一代大模型预训练范式，从模型结构、训练策略、数据策略、算力利用率等角度切入，打造具有更强能力和更高潜力的基座模型。\n1）设计更高效的模型结构，提高给定数据量、计算量、硬件型号、输出序列长度等约束下的模型能力，如长序列能力、记忆能力等。\n2）探索更科学的训练策略，对影响training dynamic的关键变量（如学习率、batchsize、初始化等）形成更科学的认知，探索更适合大模型的optimizer等。\n3）研究模型结构和数据的耦合关系，优化分阶段训练范式。\n4）结合MLsys解决大规模训练中遇到的卡点问题，实现算法和工程联合设计。\n\n任职要求\n1）熟悉NLP、LLM、MLsys、Optimization、OR、Control、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉Pytorch、 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、香港特别行政区、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153873006","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】统一化的检索生成框架探索与评测","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153873006&jobShareType=1","duty":"引入外部知识检索是处理 agent 在有限记忆存储下知识局限性的主流路径（如检索增强生成），可以有效降低幻觉比例，使生成内容具备时效性和事实性。但现有问题是检索和生成模块通常作为异质系统交替使用，无法深度协同和统一优化。近期生成式检索方向的研究为二者统一创造了条件。\n本课题希望彻底统一检索生成，研究内容包括但不限于：\n1）统一检索生成的推理和优化算法构建。\n2）优化实验在数据和计算维度的规模化。\n3）agent 视角对 RAG 和 long-context 的解读和相应评测评估方案。\n4）从统一检索生成到模型记忆的外推。","requirements":"1）熟悉大模型相关的推理、训练框架，有较强的工程实践能力和经验。\n2）有一定的学术研究背景，对前沿技术保持好奇心，学习能力和自驱力强。\n加分项：\n1）在有影响力的开源项目中做出核心贡献。\n2）发表过高质量学术论文。","description":"岗位职责\n引入外部知识检索是处理 agent 在有限记忆存储下知识局限性的主流路径（如检索增强生成），可以有效降低幻觉比例，使生成内容具备时效性和事实性。但现有问题是检索和生成模块通常作为异质系统交替使用，无法深度协同和统一优化。近期生成式检索方向的研究为二者统一创造了条件。\n本课题希望彻底统一检索生成，研究内容包括但不限于：\n1）统一检索生成的推理和优化算法构建。\n2）优化实验在数据和计算维度的规模化。\n3）agent 视角对 RAG 和 long-context 的解读和相应评测评估方案。\n4）从统一检索生成到模型记忆的外推。\n\n任职要求\n1）熟悉大模型相关的推理、训练框架，有较强的工程实践能力和经验。\n2）有一定的学术研究背景，对前沿技术保持好奇心，学习能力和自驱力强。\n加分项：\n1）在有影响力的开源项目中做出核心贡献。\n2）发表过高质量学术论文。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153889354","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】生活服务领域基座增强技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153889354&jobShareType=1","duty":"本课题探索大模型垂直领域知识高效增强方法，包括数据策略、训练策略以及scaling law友好的训练方法，打造适配实际应用所需的基座能力。研究内容包括但不限于：\n1） 大模型基座知识能力增强，通过大规模continue pretrain打造生活服务领域基座，赋能美团各类大模型应用场景。\n2）探索预训练增强阶段的大规模高质量数据自动合成、Scaling Law、长链条复杂推理反思能力增强。\n3）建设生活服务chat模型与智能体，通过强化学习等方式增强模型推理反思、复杂指令遵循、高情商交互等能力，支撑大模型在生活服务领域的应用。","requirements":"1）对NLP、大模型等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）有过预训练经验、深度推理、强化学习等方向的经验。\n3）发表过高水平论文。","description":"岗位职责\n本课题探索大模型垂直领域知识高效增强方法，包括数据策略、训练策略以及scaling law友好的训练方法，打造适配实际应用所需的基座能力。研究内容包括但不限于：\n1） 大模型基座知识能力增强，通过大规模continue pretrain打造生活服务领域基座，赋能美团各类大模型应用场景。\n2）探索预训练增强阶段的大规模高质量数据自动合成、Scaling Law、长链条复杂推理反思能力增强。\n3）建设生活服务chat模型与智能体，通过强化学习等方式增强模型推理反思、复杂指令遵循、高情商交互等能力，支撑大模型在生活服务领域的应用。\n\n任职要求\n1）对NLP、大模型等相关领域一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟练使用深度学习框架（比如PyTorch），熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）在知名开源项目中有核心贡献者优先。\n2）有过预训练经验、深度推理、强化学习等方向的经验。\n3）发表过高水平论文。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153937173","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大规模 Post-training 算法架构前沿研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153937173&jobShareType=1","duty":"Post-training 是提升大模型专项能力的核心技术方向之一，包括不限于复杂推理（Reasoning）、价值观对齐（Alignment）、业务Agent应用等研究方向。\n本课题研究方向包括但不限于：\n1）实现高效灵活的多模型强化学习训练架构。\n2）通过合理灵活动态配置资源，提升PPO及各变种算法运行效率。\n3）研究低精度在 Post-training 中的应用方式。\n4）研究不同的算法+数据对效果的影响。\n5）在复杂框架下，研究如何高效的追踪记录训练过程，提升算法探索效率。","requirements":"1）熟悉大规模分布式训练、推理、量化等技术之一。\n2）熟悉常用的训练推理框架，vLLM、SGLang、Megatron、Deepspeed等。\n3）熟悉强化学习算法。\n加分项：相关领域开源项目或发表高水平论文。","description":"岗位职责\nPost-training 是提升大模型专项能力的核心技术方向之一，包括不限于复杂推理（Reasoning）、价值观对齐（Alignment）、业务Agent应用等研究方向。\n本课题研究方向包括但不限于：\n1）实现高效灵活的多模型强化学习训练架构。\n2）通过合理灵活动态配置资源，提升PPO及各变种算法运行效率。\n3）研究低精度在 Post-training 中的应用方式。\n4）研究不同的算法+数据对效果的影响。\n5）在复杂框架下，研究如何高效的追踪记录训练过程，提升算法探索效率。\n\n任职要求\n1）熟悉大规模分布式训练、推理、量化等技术之一。\n2）熟悉常用的训练推理框架，vLLM、SGLang、Megatron、Deepspeed等。\n3）熟悉强化学习算法。\n加分项：相关领域开源项目或发表高水平论文。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153953328","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】面向真实物理世界的大规模智能体研究（Agent In Real Life）","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153953328&jobShareType=1","duty":"随着 LLM 与 RL 技术的飞速发展，具备自主决策与执行能力的 Agent 系统成为 AI 领域的前沿研究方向。本课题聚焦于构建能够在真实物理世界（餐饮、购物、旅行规划等）复杂场景下自主运行的 Agent 系统，解决传统 AI 系统难以应对的多步骤规划、长期目标追踪、环境适应性等核心挑战。主要研究内容包括但不限于：\n1）自主规划与决策：研究基于 LLM 的 CoT 等的复杂推理机制，使 Agent 能够自主分解并解决如\"为一家四口安排一个周末出游计划，包括交通、住宿、餐饮和活动\"等多步骤任务；开发能够在规划失败时进行自我修正和重新规划的自适应决策框架，突破传统 Agent 在复杂场景下的规划瓶颈。\n2）强化学习驱动的自主优化：应用前沿强化学习算法（如PPO、GRPO、RL）优化 Agent 的决策系统，通过用户反馈和任务完成度构建复杂奖励函数；研究如何在高维状态空间和长期依赖问题中有效进行奖励分配，解决真实复杂物理场景中典型的延迟反馈和稀疏奖励挑战。\n3）多 Agent 协作与分布式决策：设计基于角色分工的多 Agent 协作框架，使不同专长的 Agent 能够协同解决复杂任务，如\"美食专家 Agent 负责菜品推荐，规划 Agent 负责整体行程安排\"等；研究 Agent 间的通信协议和共识机制，解决分布式决策中的冲突协调和资源分配问题。","requirements":"1）硕士及以上学历，计算机科学、人工智能或相关专业背景。\n2）熟练掌握 Python，熟悉 PyTorch 或 TensorFlow 等深度学习框架。\n3）扎实的 LLM 和 Agent 系统理论基础。\n4）熟悉 RL 算法框架，具备将 RL 应用于 Agent 决策优化的实践经验。\n5）具备设计复杂 Agent 系统架构的能力，包括记忆机制、规划模块、执行模块等核心组件。\n加分项：\n1）在NeurIPS、ICLR、ICML、ACL、EMNLP等顶级会议发表过 Agent 系统或相关技术的论文。\n2）参与过开源 Agent 项目（如LangChain、AutoGPT 等）的开发或有重要贡献。\n3）具备多 Agent 系统设计和协作机制研究经验，了解 Agent 间通信和任务分配技术。\n4）有构建端到端 Agent 系统的实际项目经验，能够解决生产环境中的鲁棒性和可靠性问题。","description":"岗位职责\n随着 LLM 与 RL 技术的飞速发展，具备自主决策与执行能力的 Agent 系统成为 AI 领域的前沿研究方向。本课题聚焦于构建能够在真实物理世界（餐饮、购物、旅行规划等）复杂场景下自主运行的 Agent 系统，解决传统 AI 系统难以应对的多步骤规划、长期目标追踪、环境适应性等核心挑战。主要研究内容包括但不限于：\n1）自主规划与决策：研究基于 LLM 的 CoT 等的复杂推理机制，使 Agent 能够自主分解并解决如\"为一家四口安排一个周末出游计划，包括交通、住宿、餐饮和活动\"等多步骤任务；开发能够在规划失败时进行自我修正和重新规划的自适应决策框架，突破传统 Agent 在复杂场景下的规划瓶颈。\n2）强化学习驱动的自主优化：应用前沿强化学习算法（如PPO、GRPO、RL）优化 Agent 的决策系统，通过用户反馈和任务完成度构建复杂奖励函数；研究如何在高维状态空间和长期依赖问题中有效进行奖励分配，解决真实复杂物理场景中典型的延迟反馈和稀疏奖励挑战。\n3）多 Agent 协作与分布式决策：设计基于角色分工的多 Agent 协作框架，使不同专长的 Agent 能够协同解决复杂任务，如\"美食专家 Agent 负责菜品推荐，规划 Agent 负责整体行程安排\"等；研究 Agent 间的通信协议和共识机制，解决分布式决策中的冲突协调和资源分配问题。\n\n任职要求\n1）硕士及以上学历，计算机科学、人工智能或相关专业背景。\n2）熟练掌握 Python，熟悉 PyTorch 或 TensorFlow 等深度学习框架。\n3）扎实的 LLM 和 Agent 系统理论基础。\n4）熟悉 RL 算法框架，具备将 RL 应用于 Agent 决策优化的实践经验。\n5）具备设计复杂 Agent 系统架构的能力，包括记忆机制、规划模块、执行模块等核心组件。\n加分项：\n1）在NeurIPS、ICLR、ICML、ACL、EMNLP等顶级会议发表过 Agent 系统或相关技术的论文。\n2）参与过开源 Agent 项目（如LangChain、AutoGPT 等）的开发或有重要贡献。\n3）具备多 Agent 系统设计和协作机制研究经验，了解 Agent 间通信和任务分配技术。\n4）有构建端到端 Agent 系统的实际项目经验，能够解决生产环境中的鲁棒性和可靠性问题。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153793057","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】基于多模序列建模提升原生多模态大模型智能水平","city":"北京市/香港特别行政区/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153793057&jobShareType=1","duty":"原生多模旨在统一理解与生成，从而用同一套范式处理文本、视觉、语音等各个模态的数据，从而更加自然地进行模态融合，以及通过scaling友好的训练范式，解锁模型智能的新维度。本课题研究内容包括：\n1）Pre-train：借助更好的tokenizer架构 / 数据表达 / loss设计，发挥原生多模态能够不依赖文本标注，直接学习无监督多模数据的优势，进一步提升模型能力。例如基于大规模的视频/语音数据自监督训练，对物理世界建模。\n2）Post-train：通过SFT / RL等手段，借助多模token推理解锁模型新的智能维度，提升模型解决Robot/Gaming等物理世界问题的能力。","requirements":"1）熟悉NLP、LLM、MLLM、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\n原生多模旨在统一理解与生成，从而用同一套范式处理文本、视觉、语音等各个模态的数据，从而更加自然地进行模态融合，以及通过scaling友好的训练范式，解锁模型智能的新维度。本课题研究内容包括：\n1）Pre-train：借助更好的tokenizer架构 / 数据表达 / loss设计，发挥原生多模态能够不依赖文本标注，直接学习无监督多模数据的优势，进一步提升模型能力。例如基于大规模的视频/语音数据自监督训练，对物理世界建模。\n2）Post-train：通过SFT / RL等手段，借助多模token推理解锁模型新的智能维度，提升模型解决Robot/Gaming等物理世界问题的能力。\n\n任职要求\n1）熟悉NLP、LLM、MLLM、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、香港特别行政区、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153841114","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大模型推理系统前沿研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153841114&jobShareType=1","duty":"大模型推理是大模型应用的核心能力，是影响大模型应用成本和效率的关键因素。本课题专注于大模型推理加速与分布式系统优化的前沿技术探索，通过软硬件协同设计和算法工程联合优化，降低大模型推理的应用成本，提高推理性能。\n研究内容包括但不限于：\n1）投机推理（Speculative Decoding），研究基于预测性执行的动态推理优化方法，参与设计低延迟推理框架，通过概率模型预生成候选序列以降低解码计算开销。\n2）分布式系统优化，探索多节点协同推理中的通信-计算负载均衡策略，提出基于异构硬件的混合并行调度方案，实现吞吐量提升。\n3）稀疏Transformer优化与模型压缩，通过稀疏Transformer优化以及模型压缩技术提升模型的计算效率。\n4）算子优化，熟悉硬件架构的算子优化方法，通过更高效的算子优化模型的吞吐和延时。","requirements":"岗位要求：\n1）熟悉TensorFlow、PyTorch等深度学习框架。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如ICLR,ICML,ACL,EMNLP等）。\n3）有CUDA/Triton编程经验。\n4）熟悉vllm/sglang/trt-llm/lmdeploy等开源推理框架。","description":"岗位职责\n大模型推理是大模型应用的核心能力，是影响大模型应用成本和效率的关键因素。本课题专注于大模型推理加速与分布式系统优化的前沿技术探索，通过软硬件协同设计和算法工程联合优化，降低大模型推理的应用成本，提高推理性能。\n研究内容包括但不限于：\n1）投机推理（Speculative Decoding），研究基于预测性执行的动态推理优化方法，参与设计低延迟推理框架，通过概率模型预生成候选序列以降低解码计算开销。\n2）分布式系统优化，探索多节点协同推理中的通信-计算负载均衡策略，提出基于异构硬件的混合并行调度方案，实现吞吐量提升。\n3）稀疏Transformer优化与模型压缩，通过稀疏Transformer优化以及模型压缩技术提升模型的计算效率。\n4）算子优化，熟悉硬件架构的算子优化方法，通过更高效的算子优化模型的吞吐和延时。\n\n任职要求\n岗位要求：\n1）熟悉TensorFlow、PyTorch等深度学习框架。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如ICLR,ICML,ACL,EMNLP等）。\n3）有CUDA/Triton编程经验。\n4）熟悉vllm/sglang/trt-llm/lmdeploy等开源推理框架。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153873069","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】多模态智能体算法研究与自主规划","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153873069&jobShareType=1","duty":"自主任务执行的计算智能体是AI应用的重要场景之一，具备充分的技术深度(如浅层环境感知能力和深层规划决策能力)和广泛的应用价值(如智能助手、具身智能等)。本课题旨在构建业界前沿的多模态智能体，包括2D数字世界的Computer Use和Browser Use，以及3D物理世界的具身智能等能力。探索优化智能体在视觉理解、决策反思、强化学习等方向的技术挑战。\n研究内容包括：\n1）智能体算法优化：提升智能体视觉定位和决策反思水平，探索强化学习在智能体决策的应用价值，构建2D数字和3D物理环境的环境感知能力。\n2）Compute & Brower Use：探索多模态大模型自主规划完成计算机、手机、互联网网页的操作能力。\n3）具身智能：探索多模态大模型的空间理解和自主规划能力，能够完成物理世界操作能力。","requirements":"1）在CV、NLP、多模态等相关领域有其中一个或多个方向有深入的研究经历。\n2）熟悉TensorFlow、PyTorch等深度学习框架。\n3）熟练使用Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,CVPR,ICCV,ECCV等）。","description":"岗位职责\n自主任务执行的计算智能体是AI应用的重要场景之一，具备充分的技术深度(如浅层环境感知能力和深层规划决策能力)和广泛的应用价值(如智能助手、具身智能等)。本课题旨在构建业界前沿的多模态智能体，包括2D数字世界的Computer Use和Browser Use，以及3D物理世界的具身智能等能力。探索优化智能体在视觉理解、决策反思、强化学习等方向的技术挑战。\n研究内容包括：\n1）智能体算法优化：提升智能体视觉定位和决策反思水平，探索强化学习在智能体决策的应用价值，构建2D数字和3D物理环境的环境感知能力。\n2）Compute & Brower Use：探索多模态大模型自主规划完成计算机、手机、互联网网页的操作能力。\n3）具身智能：探索多模态大模型的空间理解和自主规划能力，能够完成物理世界操作能力。\n\n任职要求\n1）在CV、NLP、多模态等相关领域有其中一个或多个方向有深入的研究经历。\n2）熟悉TensorFlow、PyTorch等深度学习框架。\n3）熟练使用Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,CVPR,ICCV,ECCV等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153985413","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】具身智能技术研究","city":"北京市/上海市/深圳市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153985413&jobShareType=1","duty":"深度参与具身智能“感知-决策-行动”技术全链路的技术攻关，在以下一个或多个方向上进行深入研究：\n1.感知与决策规划：提升多模态大模型在具身场景下的能力表现，包括在复杂动态环境中对物体位姿、状态、物理属性的精准理解，以及对复杂任务的任务推理与拆解能力。\n2.行动与控制：基于真机示教数据以及海量互联网视频数据，训练机器人掌握高精度的操作技能。在机器人上研究并实践强化学习算法，优化机器人的动作策略，提升其在物理世界中的动作鲁棒性和技能泛化。\n3.仿真与虚实迁移：参与构建高逼真度的物理仿真环境（如 Isaac Sim, SAPIEN 等），用于大规模、低成本地训练和验证具身智能算法。","requirements":"1.计算机科学、机器人学、人工智能、自动化或相关领域的在读硕士或博士研究生。\n2.具备扎实的编程能力，精通 Python，熟悉 C++者优先，且熟练掌握 PyTorch 框架。\n3.对机器学习、深度学习、计算机视觉等领域有深入的理论理解。\n4.在具身智能领域有深入研究，熟悉 VLA的前沿模型。\n5.对具身智能和机器人技术抱有浓厚兴趣和热情，具备出色的自驱力、快速学习能力和解决问题的能力。\n6.在ICRA, CVPR, ICLR, IROS等人工智能或机器人学会议上有论文发表者。","description":"岗位职责\n深度参与具身智能“感知-决策-行动”技术全链路的技术攻关，在以下一个或多个方向上进行深入研究：\n1.感知与决策规划：提升多模态大模型在具身场景下的能力表现，包括在复杂动态环境中对物体位姿、状态、物理属性的精准理解，以及对复杂任务的任务推理与拆解能力。\n2.行动与控制：基于真机示教数据以及海量互联网视频数据，训练机器人掌握高精度的操作技能。在机器人上研究并实践强化学习算法，优化机器人的动作策略，提升其在物理世界中的动作鲁棒性和技能泛化。\n3.仿真与虚实迁移：参与构建高逼真度的物理仿真环境（如 Isaac Sim, SAPIEN 等），用于大规模、低成本地训练和验证具身智能算法。\n\n任职要求\n1.计算机科学、机器人学、人工智能、自动化或相关领域的在读硕士或博士研究生。\n2.具备扎实的编程能力，精通 Python，熟悉 C++者优先，且熟练掌握 PyTorch 框架。\n3.对机器学习、深度学习、计算机视觉等领域有深入的理论理解。\n4.在具身智能领域有深入研究，熟悉 VLA的前沿模型。\n5.对具身智能和机器人技术抱有浓厚兴趣和热情，具备出色的自驱力、快速学习能力和解决问题的能力。\n6.在ICRA, CVPR, ICLR, IROS等人工智能或机器人学会议上有论文发表者。\n\n工作城市\n北京市、上海市、深圳市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153650004","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】多模态大模型复杂推理","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153650004&jobShareType=1","duty":"多模态推理是大模型迈向通用人工智能的关键能力，涉及跨视觉、语言等多种模态的信息整合与深度理解。本课题聚焦于探究多模态生成式大模型的复杂推理发生机制，研究模型如何协同处理、融合和推理来自不同感知通道的信息，从而提升在复杂任务中的认知表现。\n研究内容:\n1）多模态复杂任务推理机制探究：探索强化学习机制，激发推理思维链策略，分析不同模态间信息融合在复杂跨模态推理中的作用，研究视觉-语言长距离依赖关系建模方法。\n2）多模态复杂推理与通用任务有效统一范式研究:  分析通用多模态通用任务与复杂推理任务的区别与联系，探索使用单一模型有效统一两者的范式，实现模型自适应地根据不同问题来进行不同长度的思考回答。","requirements":"1）在CV、NLP、多模态等相关领域有其中一个或多个方向有深入的研究经历。\n2）熟悉TensorFlow、PyTorch等深度学习框架。\n3）熟练使用Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,CVPR,ICCV,ECCV等）。","description":"岗位职责\n多模态推理是大模型迈向通用人工智能的关键能力，涉及跨视觉、语言等多种模态的信息整合与深度理解。本课题聚焦于探究多模态生成式大模型的复杂推理发生机制，研究模型如何协同处理、融合和推理来自不同感知通道的信息，从而提升在复杂任务中的认知表现。\n研究内容:\n1）多模态复杂任务推理机制探究：探索强化学习机制，激发推理思维链策略，分析不同模态间信息融合在复杂跨模态推理中的作用，研究视觉-语言长距离依赖关系建模方法。\n2）多模态复杂推理与通用任务有效统一范式研究:  分析通用多模态通用任务与复杂推理任务的区别与联系，探索使用单一模型有效统一两者的范式，实现模型自适应地根据不同问题来进行不同长度的思考回答。\n\n任职要求\n1）在CV、NLP、多模态等相关领域有其中一个或多个方向有深入的研究经历。\n2）熟悉TensorFlow、PyTorch等深度学习框架。\n3）熟练使用Python、C++等至少一门编程语言，熟悉LINUX环境。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,CVPR,ICCV,ECCV等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153713631","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】视频生成大模型技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153713631&jobShareType=1","duty":"研究方向包括但不限于：\n1).高效率、低精度损失、高压缩比的视频VAE和tokenizer。\n2)围绕DiT结构的高效训练和推理探索，包括稀疏架构、MoE、AR生成等。\n3) 视频生成下游功能拓展，包括多概念注入生成、交互式生成、长视频生成等。","requirements":"1）熟悉扩散模型等相关研究进展。\n2）熟悉PyTorch，有充分的动手实践经验。\n加分项：\n1）有图像/视频生成相关研究和实习经历，有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文（如ICLR、CVPR、ICCV等），有相关竞赛经历并取得名次。","description":"岗位职责\n研究方向包括但不限于：\n1).高效率、低精度损失、高压缩比的视频VAE和tokenizer。\n2)围绕DiT结构的高效训练和推理探索，包括稀疏架构、MoE、AR生成等。\n3) 视频生成下游功能拓展，包括多概念注入生成、交互式生成、长视频生成等。\n\n任职要求\n1）熟悉扩散模型等相关研究进展。\n2）熟悉PyTorch，有充分的动手实践经验。\n加分项：\n1）有图像/视频生成相关研究和实习经历，有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文（如ICLR、CVPR、ICCV等），有相关竞赛经历并取得名次。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153633714","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】语音多模态及深度推理大模型应用技术研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153633714&jobShareType=1","duty":"该课题聚焦于利用语音多模态大模型以及深度推理大模型构建对话Agent，通过实时全双工交互，精准理解和感知用户情绪，凭借高情商为用户提供极具价值的回复，旨在为用户打造温暖、贴心且高度智能的对话Agent。研究内容：​\n1）参与语音多模态大模型在客服、销售、C端助理等场景应用技术研究，通过文本-语音的对齐机制等措施，提升模型对语音中包含的语义以及声学信息的实时理解与处理能力，通过加入业务知识，增强对业务场景知识遵循能力。\n2）结合客服、销售、C端助理等业务问题，研究大模型反思、规划、决策等深度推理能力，提升模型回复的拟人度及回复准确性。","requirements":"1）熟悉LLM、Speech Codec、NLP Dialog、语音（ASR / TTS）、情感分析等相关领域，对至少一个方向有深入研究，并有实际项目经验，能够将理论知识应用于实践。​\n2）有扎实的大模型实践和研究能力，尤其是在推理和决策优化领域具有深刻的理解。\n3）熟练掌握 Python 等编程语言，具备良好的编程习惯与代码能力，熟悉 Linux 开发环境。​\n4）熟悉 Megatron、DeepSpeed 等开源训练框架。​","description":"岗位职责\n该课题聚焦于利用语音多模态大模型以及深度推理大模型构建对话Agent，通过实时全双工交互，精准理解和感知用户情绪，凭借高情商为用户提供极具价值的回复，旨在为用户打造温暖、贴心且高度智能的对话Agent。研究内容：​\n1）参与语音多模态大模型在客服、销售、C端助理等场景应用技术研究，通过文本-语音的对齐机制等措施，提升模型对语音中包含的语义以及声学信息的实时理解与处理能力，通过加入业务知识，增强对业务场景知识遵循能力。\n2）结合客服、销售、C端助理等业务问题，研究大模型反思、规划、决策等深度推理能力，提升模型回复的拟人度及回复准确性。\n\n任职要求\n1）熟悉LLM、Speech Codec、NLP Dialog、语音（ASR / TTS）、情感分析等相关领域，对至少一个方向有深入研究，并有实际项目经验，能够将理论知识应用于实践。​\n2）有扎实的大模型实践和研究能力，尤其是在推理和决策优化领域具有深刻的理解。\n3）熟练掌握 Python 等编程语言，具备良好的编程习惯与代码能力，熟悉 Linux 开发环境。​\n4）熟悉 Megatron、DeepSpeed 等开源训练框架。​\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153792897","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大模型模型压缩技术探索","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153792897&jobShareType=1","duty":"本课题专注于大模型前沿压缩技术探索，通过压缩技术降低大模型的推理部署成本。课题研究内容包括但不限于:\n1) 探索多种模态（文本、语音、视觉）的模型压缩技术，不限剪枝、蒸馏、稀疏、量化、低秩化。\n2) 探索新轻量化结构，不限 MoE、Mamba、Sparse-Attention、MTP，实现训练和推理的协同优化。\n3) 探索低精度量化算法，以及新型量化格式，不限预训练和后训练过程，实现大模型的极致压缩。\n4) 高性能算子设计和开发，实现极致的压缩推理性能。","requirements":"1）熟悉常用的模型压缩技术：剪枝、量化、蒸馏、稀疏化。\n2）熟悉 vLLM、SGLang 等开源推理框架。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\n本课题专注于大模型前沿压缩技术探索，通过压缩技术降低大模型的推理部署成本。课题研究内容包括但不限于:\n1) 探索多种模态（文本、语音、视觉）的模型压缩技术，不限剪枝、蒸馏、稀疏、量化、低秩化。\n2) 探索新轻量化结构，不限 MoE、Mamba、Sparse-Attention、MTP，实现训练和推理的协同优化。\n3) 探索低精度量化算法，以及新型量化格式，不限预训练和后训练过程，实现大模型的极致压缩。\n4) 高性能算子设计和开发，实现极致的压缩推理性能。\n\n任职要求\n1）熟悉常用的模型压缩技术：剪枝、量化、蒸馏、稀疏化。\n2）熟悉 vLLM、SGLang 等开源推理框架。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153761150","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】预训练架构优化","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153761150&jobShareType=1","duty":"本课题专注于大规模预训练场景下，分布式系统架构优化前沿技术探索。通过软硬件协同设计和算法工程联合优化，降低大规模预训练的成本和迭代周期。\n研究内容包括但不限于：1）多维并行架构的优化，如流水线并行（PP）、张量并行（TP）、数据并行（DP）等并行架构在特定硬件、模型架构下的联合优化。\n2）MoE 模型结构和训练工程架构的联合优化探索，如大量小专家场景的训练结构优化。\n3）联合算法工程师深入合作，进行Attention机制的训练策略和架构优化探索，如线性注意力、稀疏注意力等，提升超长序列建模效果和训练效率。\n4）优化多芯片架构、异地多机房环境下的异构训练系统，解锁大规模训练上推的单地域机房容量和电力限制。\n5）FP8、FP4 等低精度浮点数下的训练策略和训练性能优化探索。","requirements":"海内外高校在校学生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前5%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。","description":"岗位职责\n本课题专注于大规模预训练场景下，分布式系统架构优化前沿技术探索。通过软硬件协同设计和算法工程联合优化，降低大规模预训练的成本和迭代周期。\n研究内容包括但不限于：1）多维并行架构的优化，如流水线并行（PP）、张量并行（TP）、数据并行（DP）等并行架构在特定硬件、模型架构下的联合优化。\n2）MoE 模型结构和训练工程架构的联合优化探索，如大量小专家场景的训练结构优化。\n3）联合算法工程师深入合作，进行Attention机制的训练策略和架构优化探索，如线性注意力、稀疏注意力等，提升超长序列建模效果和训练效率。\n4）优化多芯片架构、异地多机房环境下的异构训练系统，解锁大规模训练上推的单地域机房容量和电力限制。\n5）FP8、FP4 等低精度浮点数下的训练策略和训练性能优化探索。\n\n任职要求\n海内外高校在校学生，且以下条件至少满足一项：\n1）超级学霸：专业成绩排名前5%。\n2）学术达人：在顶级期刊或学术会议上以第一作者身份发表论文（或导师一作，自己为二作）。\n3）竞赛大神：在顶级大赛上获奖。\n4）工程高手：有大厂实验室的实习经验，或有贡献突出的开源项目。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153665236","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】大模型复杂推理前沿研究","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153665236&jobShareType=1","duty":"Reasoning（推理）是大模型理解和处理信息的核心能力，是通用智能水平逼近的重要观测维度。课题聚焦于探究生成式模型的高级推理发生机制，提升大模型在复杂任务上的推理表现。\n研究内容包括但不限于：\n1）复杂任务推理应用效果优化，诸如逻辑推理、数学推理、代码推理、跨模态推理、多模型决策等。\n2) RL scaling，通过大规模强化学习持续提升模型推理能力。\n3）Test time scaling，通过增加inference时消费的算力持续提升模型推理能力。","requirements":"1）熟悉NLP、LLM、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n4）熟悉PPO、DPO、GRPO等常用RL算法。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。","description":"岗位职责\nReasoning（推理）是大模型理解和处理信息的核心能力，是通用智能水平逼近的重要观测维度。课题聚焦于探究生成式模型的高级推理发生机制，提升大模型在复杂任务上的推理表现。\n研究内容包括但不限于：\n1）复杂任务推理应用效果优化，诸如逻辑推理、数学推理、代码推理、跨模态推理、多模型决策等。\n2) RL scaling，通过大规模强化学习持续提升模型推理能力。\n3）Test time scaling，通过增加inference时消费的算力持续提升模型推理能力。\n\n任职要求\n1）熟悉NLP、LLM、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python、C++等至少一门编程语言，熟悉LINUX环境。\n3）熟悉 Megatron、DeepSpeed 等开源训练框架。\n4）熟悉PPO、DPO、GRPO等常用RL算法。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3153761434","sourceKey":"meituan","company":"美团","title":"【大模型北斗实习】代码大模型","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3153761434&jobShareType=1","duty":"随着AI技术的突破，代码大模型正成为软件开发领域的核心驱动力。基于LLM的代码生成工具已实现从自然语言描述到高质量代码的自动化生成，带来开发效率的大幅提升。本课题旨在打造行业的代码大模型，并推动Coding Agent在实际应用场景落地。 研究内容：\n1）通过代码pretrain、continue train、SFT、RL等手段，提升大模型的代码能力。\n2）构建高质量代码语料库，涵盖多语言、多场景的工业级代码数据。\n3）研发Coding Agent，支持代码生成、编辑、单测生成等领域的落地应用。","requirements":"1）熟悉NLP、LLM、MLsys、Optimization、OR、Control、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python等至少一门编程语言，熟悉LINUX环境。\n3）熟悉Pytorch、 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n3）KDDCup等业界知名机器学习比赛中获奖经历。","description":"岗位职责\n随着AI技术的突破，代码大模型正成为软件开发领域的核心驱动力。基于LLM的代码生成工具已实现从自然语言描述到高质量代码的自动化生成，带来开发效率的大幅提升。本课题旨在打造行业的代码大模型，并推动Coding Agent在实际应用场景落地。 研究内容：\n1）通过代码pretrain、continue train、SFT、RL等手段，提升大模型的代码能力。\n2）构建高质量代码语料库，涵盖多语言、多场景的工业级代码数据。\n3）研发Coding Agent，支持代码生成、编辑、单测生成等领域的落地应用。\n\n任职要求\n1）熟悉NLP、LLM、MLsys、Optimization、OR、Control、RL等相关领域，对其中一个或多个方向有深入的研究经历，且有相关实际项目经验。\n2）熟悉Python等至少一门编程语言，熟悉LINUX环境。\n3）熟悉Pytorch、 Megatron、DeepSpeed 等开源训练框架。\n加分项：\n1）有影响力的开源项目中做出过核心贡献。\n2）发表过高水平论文优先（如NeurIPS,ICLR,ICML,ACL,EMNLP等）。\n3）KDDCup等业界知名机器学习比赛中获奖经历。\n\n工作城市\n北京市、上海市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3346904295","sourceKey":"meituan","company":"美团","title":"IP运营","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3346904295&jobShareType=1","duty":"1.负责IP的运营工作，包括内容策划、推广、用户运营等相关工作。\n2.负责IP的日常管理和维护，保证产品的稳定运行和用户体验。\n3.跟进IP的数据分析和运营效果评估，制定相应的优化方案。\n4.与团队合作，共同推动IP的发展和增长。","requirements":"1.大学本科及以上学历，专业不限。\n2.对互联网产品有一定的了解，有过抖音、快手、小红书、账号运营成功经验的优先考虑。\n3.具备良好的沟通能力和团队合作精神，能够承受一定的工作压力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责IP的运营工作，包括内容策划、推广、用户运营等相关工作。\n2.负责IP的日常管理和维护，保证产品的稳定运行和用户体验。\n3.跟进IP的数据分析和运营效果评估，制定相应的优化方案。\n4.与团队合作，共同推动IP的发展和增长。\n\n岗位基本要求\n1.大学本科及以上学历，专业不限。\n2.对互联网产品有一定的了解，有过抖音、快手、小红书、账号运营成功经验的优先考虑。\n3.具备良好的沟通能力和团队合作精神，能够承受一定的工作压力。\n\n岗位亮点\n业务增长空间巨大，团队氛围愉快，有展现能力的绝佳舞台","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3369700031","sourceKey":"meituan","company":"美团","title":"大模型数据运营-小语种/方言方向实习生","city":"北京市/成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3369700031&jobShareType=1","duty":"1. 深入理解多模态大模型，调研多语种语音音系特征、完善标注规范、验收数据质量，为业务和算法提供知识技能支持；\n2. 负责大模型语音数据的质量监控或验收等工作，并定期对语音技术效果做出评价与反馈；\n3. 协助mentor管理一或多个语种的数据生产项目，协助产品和算法优化模型效果。","requirements":"1. 本科以上学历，语言类、小语种相关专业；\n2. 小语种方向：法语、日语、俄语、葡萄牙语专业，同时具备英文专四/专八/雅思/托福证书优先；\n3. 方言方向：北京话、西安话、上海话、东北话、河南话；\n4. 逻辑推理方向：俄语、英语，具备一定python脚本书写能力\n5. 需具备口音判断、文字校对能力，听力能力优秀者优先；\n6. 专业知识基础扎实，熟悉语言学研究方法；\n7. 具备语音数据标注执行/管理经验；\n8. 团队协作意识强，性格良好，业务意识强。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 深入理解多模态大模型，调研多语种语音音系特征、完善标注规范、验收数据质量，为业务和算法提供知识技能支持；\n2. 负责大模型语音数据的质量监控或验收等工作，并定期对语音技术效果做出评价与反馈；\n3. 协助mentor管理一或多个语种的数据生产项目，协助产品和算法优化模型效果。\n\n岗位基本要求\n1. 本科以上学历，语言类、小语种相关专业；\n2. 小语种方向：法语、日语、俄语、葡萄牙语专业，同时具备英文专四/专八/雅思/托福证书优先；\n3. 方言方向：北京话、西安话、上海话、东北话、河南话；\n4. 逻辑推理方向：俄语、英语，具备一定python脚本书写能力\n5. 需具备口音判断、文字校对能力，听力能力优秀者优先；\n6. 专业知识基础扎实，熟悉语言学研究方法；\n7. 具备语音数据标注执行/管理经验；\n8. 团队协作意识强，性格良好，业务意识强。\n\n岗位亮点\n1.丰富的实习经验，提供良好的职业发展机会。\n2.参与大模型语音数据运营工作，积累相关领域的专业知识和经验。\n3.与专业团队合作，学习并掌握先进的数据运营和分析技术，提升个人能力和竞争力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3197882635","sourceKey":"meituan","company":"美团","title":"产品实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3197882635&jobShareType=1","duty":"1.负责供应商履约、治理模块，识别业务需求及痛点，推动流程线上化\n2.对供应商的核心指标归因分析及下探改善，实现指标达成及业务业绩的优化\n3.关注行业动态及市场同类产品，形成产品改良方案并推动落地\n4.通过与业务及横向团队深入协作，提炼共性需求，建设通用能力为业务发展赋能，帮助业务持续达成目标","requirements":"1.能够到岗实习，每周至少实习4天，能长期实习优先\n2.有后台、电商相关产品经验优先\n3.具备跨部门多线程协调沟通能力，能够推动项目上线","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责供应商履约、治理模块，识别业务需求及痛点，推动流程线上化\n2.对供应商的核心指标归因分析及下探改善，实现指标达成及业务业绩的优化\n3.关注行业动态及市场同类产品，形成产品改良方案并推动落地\n4.通过与业务及横向团队深入协作，提炼共性需求，建设通用能力为业务发展赋能，帮助业务持续达成目标\n\n岗位基本要求\n1.能够到岗实习，每周至少实习4天，能长期实习优先\n2.有后台、电商相关产品经验优先\n3.具备跨部门多线程协调沟通能力，能够推动项目上线\n\n岗位亮点\n大平台，较大的成长空间，能深入业务，快速提升个人能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3289433333","sourceKey":"meituan","company":"美团","title":"【无人车北斗实习】自动驾驶算法与系统研究实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3289433333&jobShareType=1","duty":"基于数据驱动模型端到端一体化的长期需求，我们寻找有极强的技术信仰与热情，富有好奇心和驱动力的候选人。参与探索自动驾驶面向未来的算法设计和工程优化的综合性问题。\n1.探究自动驾驶领域分布式训练的效率极限，通过底层硬件和分布式集群/存储优化，结合深度学习框架特性和算子性能优化，达到MFU上限。\n2.基于VLM、LLM等大模型技术和无人配送的业务特点，探索自动驾驶新一代的模型结构范式，推动自动驾驶技术的进一步发展。","requirements":"1.2026届本科及以上学历，人工智能、计算机、自动化、数学相关专业优先；\n2.扎实的机器学习、CV、LLM基础和出色的探索能力。具备自动驾驶或大模型领域相关算法知识；\n3.优秀的代码能力、数据结构和基础算法功底，熟练掌握C/C++或Python。有竞赛经历优先；\n4.极强的技术信仰与热情，对自动驾驶充满乐趣；\n5.富有好奇心和驱动力，了解大模型社区相关技术发展。\n\n岗位亮点：\n1.可以参与自动车团队部门级别的核心工程优化项目，学习到包括大模型领域前沿的算力效率优化技巧，锻炼ai infra相关技能。\n2.基于VLM、LLM等大模型技术，结合工程和算法，探索业务可落地的自动驾驶端到端方案。","description":"岗位职责\n基于数据驱动模型端到端一体化的长期需求，我们寻找有极强的技术信仰与热情，富有好奇心和驱动力的候选人。参与探索自动驾驶面向未来的算法设计和工程优化的综合性问题。\n1.探究自动驾驶领域分布式训练的效率极限，通过底层硬件和分布式集群/存储优化，结合深度学习框架特性和算子性能优化，达到MFU上限。\n2.基于VLM、LLM等大模型技术和无人配送的业务特点，探索自动驾驶新一代的模型结构范式，推动自动驾驶技术的进一步发展。\n\n任职要求\n1.2026届本科及以上学历，人工智能、计算机、自动化、数学相关专业优先；\n2.扎实的机器学习、CV、LLM基础和出色的探索能力。具备自动驾驶或大模型领域相关算法知识；\n3.优秀的代码能力、数据结构和基础算法功底，熟练掌握C/C++或Python。有竞赛经历优先；\n4.极强的技术信仰与热情，对自动驾驶充满乐趣；\n5.富有好奇心和驱动力，了解大模型社区相关技术发展。\n\n岗位亮点：\n1.可以参与自动车团队部门级别的核心工程优化项目，学习到包括大模型领域前沿的算力效率优化技巧，锻炼ai infra相关技能。\n2.基于VLM、LLM等大模型技术，结合工程和算法，探索业务可落地的自动驾驶端到端方案。\n\n工作城市\n北京市","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:2731047995","sourceKey":"meituan","company":"美团","title":"大模型数据运营（英文实习）","city":"北京市/成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2731047995&jobShareType=1","duty":"1. 数据标注执行：人工对大模型训练所需的英文数据进行排序/改写 或 通过prompt engineering合成大批量高质数据，确保数据的准确性和一致性；\n2. 标注方案制定：分析模型效果、调研论文或收集行业数据，沉淀相关结果文档，支持数据方案迭代/优化；\n3. 标注项目管理：协助负责人管理内/外部标注人力，完成包括但不限于培训、质检、答疑等工作；\n4. 团队协作：与技术团队紧密合作，及时反馈问题，根据模型效果及时调整标注策略。","requirements":"1. 学历背景：27届及以后毕业的硕士/博士在读同学；英语语言文学、语言学、计算语言学、翻译等相关专业，有扎实的学科理论基础；\n2. 语言能力：英语专四优秀及以上，优先专八优秀/雅思7+/托福105+；\n3. 逻辑思维：具有良好的逻辑思维和分析能力，能够准确理解数据任务的目的和要求，并能够高效地执行复杂的数据分析任务；\n4. 沟通与协作：具备良好的沟通能力和团队协作精神，能够与团队成员有效沟通，协同解决问题，共同推进项目进度。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 数据标注执行：人工对大模型训练所需的英文数据进行排序/改写 或 通过prompt engineering合成大批量高质数据，确保数据的准确性和一致性；\n2. 标注方案制定：分析模型效果、调研论文或收集行业数据，沉淀相关结果文档，支持数据方案迭代/优化；\n3. 标注项目管理：协助负责人管理内/外部标注人力，完成包括但不限于培训、质检、答疑等工作；\n4. 团队协作：与技术团队紧密合作，及时反馈问题，根据模型效果及时调整标注策略。\n\n岗位基本要求\n1. 学历背景：27届及以后毕业的硕士/博士在读同学；英语语言文学、语言学、计算语言学、翻译等相关专业，有扎实的学科理论基础；\n2. 语言能力：英语专四优秀及以上，优先专八优秀/雅思7+/托福105+；\n3. 逻辑思维：具有良好的逻辑思维和分析能力，能够准确理解数据任务的目的和要求，并能够高效地执行复杂的数据分析任务；\n4. 沟通与协作：具备良好的沟通能力和团队协作精神，能够与团队成员有效沟通，协同解决问题，共同推进项目进度。\n\n岗位亮点\n紧跟业界前沿的大模型迭代发展，深度参与AIGC在各场景的落地应用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3099774305","sourceKey":"meituan","company":"美团","title":"服务运营实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3099774305&jobShareType=1","duty":"岗位职责:\n1.结合团队的需求，完成服务数据的快速提取、加工、分析，围绕分析目标输出有效的分析结论及改善建议；\n2.协助对接团队内数据报表的搭建及上线，提升团队内数据提取的便利度、有效性；\n3.通过对日常服务数据的拆解，监控并快速识别异常，帮助团队内部进行数据驱动决策；\n4.协助改善用户服务的工作流程、执行规范等基础制度，并能落地实施。","requirements":"1. 本科及以上学历，能够每周实习5天，持续实习4个月以上的优先考虑；\n2. 专业不限，管理类、经济类专业优先，有SQL、Python基础加分；\n3. 具备良好的逻辑思维能力和数据敏感度，能够快速发现数据中的规律和问题；\n4. 吃苦耐劳、自驱力强，做事认真、仔细、负责。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n岗位职责:\n1.结合团队的需求，完成服务数据的快速提取、加工、分析，围绕分析目标输出有效的分析结论及改善建议；\n2.协助对接团队内数据报表的搭建及上线，提升团队内数据提取的便利度、有效性；\n3.通过对日常服务数据的拆解，监控并快速识别异常，帮助团队内部进行数据驱动决策；\n4.协助改善用户服务的工作流程、执行规范等基础制度，并能落地实施。\n\n岗位基本要求\n1. 本科及以上学历，能够每周实习5天，持续实习4个月以上的优先考虑；\n2. 专业不限，管理类、经济类专业优先，有SQL、Python基础加分；\n3. 具备良好的逻辑思维能力和数据敏感度，能够快速发现数据中的规律和问题；\n4. 吃苦耐劳、自驱力强，做事认真、仔细、负责。\n\n具备以下条件优先\n有过数据分析的实习或的工作经验，有过行研经验\n\n岗位亮点\n1.能够在快节奏的工作环境中不断学习和成长，了解公司运营和业务情况；\n2.有机会接触到多层面的运营工作，提升数据分析能力和业务洞察力；\n3.参与团队日常工作，实践自己的运营能力，为未来职业发展打下基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3185613649","sourceKey":"meituan","company":"美团","title":"香港商分实习-用户研究方向","city":"香港特别行政区","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3185613649&jobShareType=1","duty":"1.收集来自商分、产品、运营、市场等多端的用户研究需求，筛选有价值的用研命题。\n2.协助设计并执行用户调研（问卷、访谈、焦点小组等），深度挖掘用户行为与痛点。\n3.对调研数据进行清洗、整理与分析，结合站内数据进行深度分析，提炼关键用户洞察，形成可落地的建议报告。\n4.联动产品、运营、技术团队，推动相关落地事项，协助优化业务流程及用户体验。","requirements":"1.大学本科或研究生在校生，商分、经济学、统计学等相关专业优先。\n2.有互联网、咨询公司实习经验优先；有商业分析、数据分析、数据基建实习经验优先。\n3.需要具备优秀的数据分析能力，掌握常用分析统计方法，熟练使用SQL语言进行数据提取并进行相应分析。\n4.逻辑清晰，擅长从复杂信息中提炼核心结论。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.收集来自商分、产品、运营、市场等多端的用户研究需求，筛选有价值的用研命题。\n2.协助设计并执行用户调研（问卷、访谈、焦点小组等），深度挖掘用户行为与痛点。\n3.对调研数据进行清洗、整理与分析，结合站内数据进行深度分析，提炼关键用户洞察，形成可落地的建议报告。\n4.联动产品、运营、技术团队，推动相关落地事项，协助优化业务流程及用户体验。\n\n岗位基本要求\n1.大学本科或研究生在校生，商分、经济学、统计学等相关专业优先。\n2.有互联网、咨询公司实习经验优先；有商业分析、数据分析、数据基建实习经验优先。\n3.需要具备优秀的数据分析能力，掌握常用分析统计方法，熟练使用SQL语言进行数据提取并进行相应分析。\n4.逻辑清晰，擅长从复杂信息中提炼核心结论。\n\n具备以下条件优先\n掌握粤语和英语优先。\n\n岗位亮点\n1.行业top商分团队实习经历，能够较全面地锻炼商分能力模型。\n2.业务前景广阔、增长快。\n3.团队文化热血、专业、开放。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:2973819681","sourceKey":"meituan","company":"美团","title":"实习-金服支付-商业分析师-北京","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2973819681&jobShareType=1","duty":"1、日常数据监控：进行日常数据报表的监测，能够及时发现问题并分析数据异常原因。\n2、异动归因：数据监控并识别异动，进行异动分析，归因业务原因，产出结论。\n3、业务数据分析：协助进行专题分析，深挖数据体现的业务问题，产出有应用性的数据结论。\n4、策略评估：协助进行策略分析工作，产出实验效果和结论。\n5、完成mentor交代的其他工作。","requirements":"1、具备良好的数理逻辑思考能力、业务理解能力和沟通表达能力。\n2、对数据敏感，学习能力强，能够快速掌握公司内部各种数据工具。\n3、熟练使用Hive/SQL，掌握基本的数据可视化和统计方法，并有相关实习经历。\n4、一周5天，并能持续5个月及以上。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、日常数据监控：进行日常数据报表的监测，能够及时发现问题并分析数据异常原因。\n2、异动归因：数据监控并识别异动，进行异动分析，归因业务原因，产出结论。\n3、业务数据分析：协助进行专题分析，深挖数据体现的业务问题，产出有应用性的数据结论。\n4、策略评估：协助进行策略分析工作，产出实验效果和结论。\n5、完成mentor交代的其他工作。\n\n岗位基本要求\n1、具备良好的数理逻辑思考能力、业务理解能力和沟通表达能力。\n2、对数据敏感，学习能力强，能够快速掌握公司内部各种数据工具。\n3、熟练使用Hive/SQL，掌握基本的数据可视化和统计方法，并有相关实习经历。\n4、一周5天，并能持续5个月及以上。\n\n岗位亮点\n完善的商分培养体系，掌握商分方法论，并在实际工作中对业务产生价值。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3118455121","sourceKey":"meituan","company":"美团","title":"AI方向产品实习生","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3118455121&jobShareType=1","duty":"1.参与AI导购、AI活动收集、AI文案生成等创新产品探索落地。\n2.进行用户需求调研和用户行为分析，收集和整理用户反馈和数据，为产品设计提供支持。\n3.参与产品迭代优化，发现和解决产品中的问题，提高产品质量和用户体验。","requirements":"1.大学本科及以上学历，计算机、人工智能、市场营销等相关专业优先。\n2.对人工智能领域有浓厚兴趣，了解AI产品的基本原理和发展趋势。\n3.具备良好的团队合作精神和沟通能力，有较强的学习能力和解决问题的能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.参与AI导购、AI活动收集、AI文案生成等创新产品探索落地。\n2.进行用户需求调研和用户行为分析，收集和整理用户反馈和数据，为产品设计提供支持。\n3.参与产品迭代优化，发现和解决产品中的问题，提高产品质量和用户体验。\n\n岗位基本要求\n1.大学本科及以上学历，计算机、人工智能、市场营销等相关专业优先。\n2.对人工智能领域有浓厚兴趣，了解AI产品的基本原理和发展趋势。\n3.具备良好的团队合作精神和沟通能力，有较强的学习能力和解决问题的能力。\n\n具备以下条件优先\n1、有AI产品、用户产品实习经验优先；\n2、对大模型行业了解，有过AI coding经验优先；\n\n岗位亮点\n1.参与大模型的用户产品探索，了解人工智能技术和产品设计前沿趋势，提升自己的技术和产品能力。\n2.与一流的产品经理和开发团队合作，学习和掌握产品设计和开发流程，了解产品上线和运营的全过程。\n3.获得丰富的实践经验，参与产品的设计、测试和优化，锻炼自己的问题解决能力和团队合作能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:2639713807","sourceKey":"meituan","company":"美团","title":"大模型数据运营-多模态视觉方向（实习生）","city":"北京市/成都市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2639713807&jobShareType=1","duty":"1. 负责多模态数据（图像、视频等）的标注工作，确保数据标注的准确性和一致性。\n2. 以专业角度，对图片、视频等内容进行美学评估。\n3. 与团队密切合作，共同迭代模型打标、模型效果评价体系。","requirements":"1. 专业背景：本科及以上学历，美术、摄影或设计相关专业背景，拥有扎实的美术基础，对色彩、构图、光影有独到见解。\n2. 摄影人士：热爱摄影，熟悉摄影技巧，能够准确评估图片的曝光、对焦、景深等摄影要素。\n3. 设计达人：具备平面设计、UI/UX设计等经验，对视觉美感有敏锐的洞察力。\n4. 职业素养：具备良好的团队协作精神和沟通能力，能够适应新业务的变化节奏。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责多模态数据（图像、视频等）的标注工作，确保数据标注的准确性和一致性。\n2. 以专业角度，对图片、视频等内容进行美学评估。\n3. 与团队密切合作，共同迭代模型打标、模型效果评价体系。\n\n岗位基本要求\n1. 专业背景：本科及以上学历，美术、摄影或设计相关专业背景，拥有扎实的美术基础，对色彩、构图、光影有独到见解。\n2. 摄影人士：热爱摄影，熟悉摄影技巧，能够准确评估图片的曝光、对焦、景深等摄影要素。\n3. 设计达人：具备平面设计、UI/UX设计等经验，对视觉美感有敏锐的洞察力。\n4. 职业素养：具备良好的团队协作精神和沟通能力，能够适应新业务的变化节奏。\n\n岗位亮点\n紧跟业界最前沿的大模型能力，深度参与AIGC在各场景的落地应用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:3072326071","sourceKey":"meituan","company":"美团","title":"前端技术组-日常实习-北京+上海","city":"北京市/上海市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3072326071&jobShareType=1","duty":"1.参与前端技术组日常实习工作，包括Web前端开发、页面优化等相关工作。\n2.负责前端技术组的项目开发和维护，保证项目的高质量和高效率完成。\n3.与团队成员协作，共同完成团队目标，提升团队整体实力。","requirements":"1.大学本科及以上学历，计算机相关专业优先。\n2.对前端技术有浓厚兴趣，具备一定的前端开发经验。\n3.具备团队合作精神，良好的沟通能力和学习能力。\n4.熟悉HTML、CSS、JavaScript等前端技术，有React、Vue等框架经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.参与前端技术组日常实习工作，包括Web前端开发、页面优化等相关工作。\n2.负责前端技术组的项目开发和维护，保证项目的高质量和高效率完成。\n3.与团队成员协作，共同完成团队目标，提升团队整体实力。\n\n岗位基本要求\n1.大学本科及以上学历，计算机相关专业优先。\n2.对前端技术有浓厚兴趣，具备一定的前端开发经验。\n3.具备团队合作精神，良好的沟通能力和学习能力。\n4.熟悉HTML、CSS、JavaScript等前端技术，有React、Vue等框架经验者优先。\n\n岗位亮点\n1.在前端技术领域有较大的发展空间，可以接触到前沿前端技术和项目。\n2.有机会与优秀的团队成员一起工作，共同成长和提升技术水平。\n3.公司提供良好的实习环境和发展机会，可以在实践中不断提升自己的技术能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan:2963188562","sourceKey":"meituan","company":"美团","title":"招聘助理","city":"北京市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2963188562&jobShareType=1","duty":"1.负责协助招聘经理进行人力资源招聘工作，包括但不限于发布招聘信息、筛选简历、安排面试等。\n2.跟进候选人的面试进程，及时与候选人沟通面试安排、面试反馈等事宜。\n3.维护并更新人才库，确保招聘信息的准确性和及时性。\n4.协助招聘经理进行候选人的背景调查和参考人员的联系。\n5.跟踪新员工的入职流程，协助完成入职手续，提供必要的培训和指导。\n6.协助招聘经理制定并执行招聘计划，确保招聘目标的达成。","requirements":"1.本科及以上学历，人力资源管理、心理学等相关专业优先考虑。\n2.具备一定的人力资源招聘工作经验，熟悉招聘流程和方法。\n3.熟练使用招聘平台、社交媒体等招聘工具，具备良好的信息收集和整理能力。\n4.具备良好的沟通能力和协调能力，能够与不同层级的候选人和团队成员有效沟通。\n5.具备团队合作精神，能够积极配合团队完成工作任务。\n6.具备较强的时间管理能力，能够在繁忙的工作环境下高效工作。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.负责协助招聘经理进行人力资源招聘工作，包括但不限于发布招聘信息、筛选简历、安排面试等。\n2.跟进候选人的面试进程，及时与候选人沟通面试安排、面试反馈等事宜。\n3.维护并更新人才库，确保招聘信息的准确性和及时性。\n4.协助招聘经理进行候选人的背景调查和参考人员的联系。\n5.跟踪新员工的入职流程，协助完成入职手续，提供必要的培训和指导。\n6.协助招聘经理制定并执行招聘计划，确保招聘目标的达成。\n\n岗位基本要求\n1.本科及以上学历，人力资源管理、心理学等相关专业优先考虑。\n2.具备一定的人力资源招聘工作经验，熟悉招聘流程和方法。\n3.熟练使用招聘平台、社交媒体等招聘工具，具备良好的信息收集和整理能力。\n4.具备良好的沟通能力和协调能力，能够与不同层级的候选人和团队成员有效沟通。\n5.具备团队合作精神，能够积极配合团队完成工作任务。\n6.具备较强的时间管理能力，能够在繁忙的工作环境下高效工作。\n\n岗位亮点\n1.丰富的人力资源招聘经验，有机会与各类优秀候选人和专业团队合作。\n2.在基础研发平台招聘团队，接触到高精尖的头部技术人才，包括但不限于AI、大数据、云等方向。\n3.可以通过参与招聘工作，锻炼自己的沟通、协调和组织能力，提升自身的职业发展空间。","jdComplete":true,"sourceStatus":"000"}];
